export interface Student {
  id: string;
  name: string;
  phoneNumber: string;
  contactType: 'student' | 'parent';
  reportTime: string; // ISO String
  recruiterId: string;
}

export interface AppUser {
  id: string;
  username: string; // Acts as the display name
  idCard: string;   // Acts as the unique identifier/password for login
  role: 'user';
  createdAt: string;
  status: 'active' | 'disabled';
}

export interface Recruiter {
  id: string;
  username: string;
  role: 'admin' | 'user';
}

export interface SystemSettings {
  reportingStartTime: string | null; // ISO String
  reportingEndTime: string | null;   // ISO String
  logoUrl?: string;
}

export interface AnalysisResult {
  summary: string;
  trend: string;
  recommendation: string;
}

export enum ViewState {
  LOGIN = 'LOGIN',
  FORM = 'FORM',
  DASHBOARD = 'DASHBOARD'
}

import { Student, Recruiter, AppUser, SystemSettings } from '../types';

const STUDENTS_KEY = 'chengdu_school_students';
const APP_USERS_KEY = 'chengdu_school_app_users';
const SETTINGS_KEY = 'chengdu_school_settings';
const CURRENT_USER_KEY = 'chengdu_school_current_user';
const ADMIN_PASSWORD_KEY = 'chengdu_school_admin_password';
const DEFAULT_PASSWORD = 'system123@';

// Mock initial admin
const MOCK_ADMIN: Recruiter = { id: 'admin-1', username: 'admin', role: 'admin' };

const generateId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

// --- Student Data ---

export const getStudents = (): Student[] => {
  try {
    const data = localStorage.getItem(STUDENTS_KEY);
    if (!data) return [];
    const parsed = JSON.parse(data);
    return Array.isArray(parsed) ? parsed.filter(item => item && typeof item === 'object') : [];
  } catch (error) {
    console.error("Error reading students", error);
    return [];
  }
};

export const saveStudent = (student: Omit<Student, 'id' | 'reportTime'>): Student => {
  const students = getStudents();
  const newStudent: Student = {
    ...student,
    id: generateId(),
    reportTime: new Date().toISOString(),
  };

  const updatedStudents = [newStudent, ...students];
  localStorage.setItem(STUDENTS_KEY, JSON.stringify(updatedStudents));
  return newStudent;
};

// --- User Management (Now for Additional Admins) ---

export const getAppUsers = (): AppUser[] => {
  try {
    const data = localStorage.getItem(APP_USERS_KEY);
    if (!data) return [];
    const parsed = JSON.parse(data);
    return Array.isArray(parsed) ? parsed.filter(item => item && typeof item === 'object') : [];
  } catch (error) {
    return [];
  }
};

export const saveAppUser = (user: Omit<AppUser, 'id' | 'createdAt' | 'role'>): AppUser => {
  const users = getAppUsers();

  // Check for duplicates
  if (users.some(u => u.idCard === user.idCard)) {
    throw new Error("该身份证号已存在");
  }

  const newUser: AppUser = {
    ...user,
    id: generateId(),
    role: 'user', // In types.ts role is 'user', but logically these act as sub-admins now. We keep type as 'user' to avoid breaking interface but treat them as admins in login.
    createdAt: new Date().toISOString(),
  };

  const updatedUsers = [newUser, ...users];
  localStorage.setItem(APP_USERS_KEY, JSON.stringify(updatedUsers));
  return newUser;
};

export const updateAppUser = (id: string, updates: Partial<AppUser>): void => {
  const users = getAppUsers();
  const updatedUsers = users.map(u => u.id === id ? { ...u, ...updates } : u);
  localStorage.setItem(APP_USERS_KEY, JSON.stringify(updatedUsers));
};

export const deleteAppUser = (id: string): void => {
  const users = getAppUsers();
  const updatedUsers = users.filter(u => u.id !== id);
  localStorage.setItem(APP_USERS_KEY, JSON.stringify(updatedUsers));
};

// --- Authentication ---

// 1. Admin Login: Checks Super Admin OR App Users (Sub-admins)
export const loginAdmin = (username: string, passwordOrIdCard: string): Recruiter | null => {
  // A. Super Admin Check
  if (username === 'admin') {
    if (verifyAdminPassword(passwordOrIdCard)) {
      return MOCK_ADMIN;
    }
    return null;
  }

  // B. Sub-Admin Check (from User Management list)
  // For sub-admins, we treat the username as Name and ID Card as the password
  const users = getAppUsers();
  const foundUser = users.find(u => 
    u.username === username && 
    u.idCard === passwordOrIdCard && 
    u.status === 'active'
  );

  if (foundUser) {
    return {
      id: foundUser.id,
      username: foundUser.username,
      role: 'admin' // Grant admin access
    };
  }

  return null;
};

// 2. Student/Reporter Login: Open access, just validation
export const validateReporter = (username: string, phoneNumber: string): Recruiter | null => {
  if (!username) return null;

  // Valid Mobile Phone Number (China)
  const phoneRegex = /^1[3-9]\d{9}$/;

  if (!phoneRegex.test(phoneNumber)) {
    return null;
  }

  return {
    id: phoneNumber, // Use Phone as temporary session ID
    username: username,
    role: 'user'
  };
};

export const verifyAdminPassword = (inputPassword: string): boolean => {
  try {
    const stored = localStorage.getItem(ADMIN_PASSWORD_KEY);
    const currentPassword = stored || DEFAULT_PASSWORD;
    if (!stored) {
      localStorage.setItem(ADMIN_PASSWORD_KEY, DEFAULT_PASSWORD);
    }
    return inputPassword === currentPassword;
  } catch {
    return false;
  }
};

export const changeAdminPassword = (newPassword: string): void => {
  try {
    localStorage.setItem(ADMIN_PASSWORD_KEY, newPassword);
  } catch (e) {
    console.error(e);
  }
};

// --- System Settings (Time Window) ---

export const getSystemSettings = (): SystemSettings => {
  try {
    const data = localStorage.getItem(SETTINGS_KEY);
    if (!data) return { reportingStartTime: null, reportingEndTime: null, logoUrl: '' };
    const parsed = JSON.parse(data);
    return parsed || { reportingStartTime: null, reportingEndTime: null, logoUrl: '' };
  } catch {
    return { reportingStartTime: null, reportingEndTime: null, logoUrl: '' };
  }
};

export const saveSystemSettings = (settings: SystemSettings): void => {
  localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
};

export const isReportingTimeValid = (): { valid: boolean; message?: string } => {
  const settings = getSystemSettings();
  const now = new Date().getTime();

  if (settings.reportingStartTime) {
    const start = new Date(settings.reportingStartTime).getTime();
    if (now < start) {
      return { valid: false, message: `系统未开放。开放时间: ${new Date(start).toLocaleString()}` };
    }
  }

  if (settings.reportingEndTime) {
    const end = new Date(settings.reportingEndTime).getTime();
    if (now > end) {
      return { valid: false, message: `报备已截止。截止时间: ${new Date(end).toLocaleString()}` };
    }
  }

  return { valid: true };
};

// --- Misc ---

export const exportToCSV = (): void => {
  const students = getStudents();
  if (students.length === 0) {
    alert("暂无数据可导出");
    return;
  }

  const headers = ["ID", "姓名", "电话", "电话归属", "报备时间", "填报人ID"];
  const csvContent = [
    headers.join(","),
    ...students.map(s => [
      s.id,
      s.name,
      s.phoneNumber,
      s.contactType === 'student' ? '学生本人' : '家长',
      new Date(s.reportTime).toLocaleString(),
      s.recruiterId
    ].join(","))
  ].join("\n");

  const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.setAttribute("href", url);
  link.setAttribute("download", `报备数据_${new Date().toISOString().slice(0,10)}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

export const getCurrentUser = (): Recruiter | null => {
  try {
    const data = localStorage.getItem(CURRENT_USER_KEY);
    return data ? JSON.parse(data) : null;
  } catch {
    return null;
  }
};

export const setCurrentUser = (user: Recruiter | null) => {
  try {
    if (user) {
      localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user));
    } else {
      localStorage.removeItem(CURRENT_USER_KEY);
    }
  } catch (e) {
    console.error("Storage error", e);
  }
};

import React, { useState, useEffect } from 'react';
import StudentForm from './components/StudentForm';
import AdminDashboard from './components/AdminDashboard';
import { Recruiter, SystemSettings } from './types';
import { loginAdmin, validateReporter, getSystemSettings } from './services/dataService';
import { School, User, Shield, ChevronRight, Smartphone, Monitor, Lock } from 'lucide-react';

type SystemMode = 'PORTAL' | 'STUDENT_APP' | 'ADMIN_APP';

const App: React.FC = () => {
  const [mode, setMode] = useState<SystemMode>('PORTAL');
  const [currentUser, setCurrentUser] = useState<Recruiter | null>(null);
  const [settings, setSettings] = useState<SystemSettings>({ reportingStartTime: null, reportingEndTime: null });

  // Authentication State for sub-apps
  const [username, setUsername] = useState('');
  const [loginPhone, setLoginPhone] = useState('');
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState('');

  // Effect to handle URL based "Routing" and Browser Back/Forward buttons
  useEffect(() => {
    const handleUrlChange = () => {
      const params = new URLSearchParams(window.location.search);
      const appParam = params.get('app');
      if (appParam === 'student') {
        setMode('STUDENT_APP');
      } else if (appParam === 'admin') {
        setMode('ADMIN_APP');
      } else {
        setMode('PORTAL');
      }
    };

    handleUrlChange();
    window.addEventListener('popstate', handleUrlChange);

    // Load Settings (for logo)
    setSettings(getSystemSettings());

    return () => window.removeEventListener('popstate', handleUrlChange);
  }, []);

  const changeMode = (newMode: SystemMode) => {
    setMode(newMode);
    const url = new URL(window.location.href);

    if (newMode === 'STUDENT_APP') {
      url.searchParams.set('app', 'student');
      window.history.pushState({}, '', url);
    } else if (newMode === 'ADMIN_APP') {
      url.searchParams.set('app', 'admin');
      window.history.pushState({}, '', url);
    } else {
      url.searchParams.delete('app');
      window.history.pushState({}, '', url);
    }
  };

  const handleLogin = (e: React.FormEvent, targetRole: 'user' | 'admin') => {
    e.preventDefault();
    setLoginError('');

    if (!username.trim()) {
      setLoginError('请输入账号/姓名');
      return;
    }

    // --- Admin Login ---
    if (targetRole === 'admin') {
      if (!password) {
        setLoginError('请输入密码 (或子管理员身份证号)');
        return;
      }

      const adminUser = loginAdmin(username.trim(), password.trim());
      if (adminUser) {
        setCurrentUser(adminUser);
      } else {
        setLoginError('登录失败：账号或密码错误');
      }
      return;
    } 

    // --- Student/User Login (Information Reporting) ---
    // No database check needed, just validation
    if (targetRole === 'user') {
      if (!loginPhone.trim()) {
        setLoginError('请输入手机号码');
        return;
      }

      const user = validateReporter(username.trim(), loginPhone.trim());

      if (user) {
        setCurrentUser(user);
      } else {
        setLoginError('登录失败：请输入有效的11位手机号码');
      }
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setUsername('');
    setLoginPhone('');
    setPassword('');
    setLoginError('');
  };

  // --- PORTAL VIEW ---
  if (mode === 'PORTAL') {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-100 to-gray-200 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-4xl">
          <div className="text-center mb-12">
            <div className="bg-school-600 w-20 h-20 rounded-2xl rotate-3 shadow-xl flex items-center justify-center mx-auto mb-6">
              <School className="text-white w-10 h-10" />
            </div>
            <h1 className="text-3xl md:text-4xl font-extrabold text-gray-800 tracking-tight">
              成都城市建设技工学校
            </h1>
            <p className="text-gray-500 mt-3 text-lg">综合信息管理平台</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <button 
              onClick={() => changeMode('STUDENT_APP')}
              className="group relative bg-white rounded-3xl p-8 shadow-xl hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1 text-left overflow-hidden border border-gray-100"
            >
              <div className="absolute top-0 right-0 bg-blue-50 w-32 h-32 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110"></div>
              <div className="relative z-10">
                <div className="bg-blue-100 w-14 h-14 rounded-2xl flex items-center justify-center mb-6 text-blue-600 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                  <Smartphone size={28} />
                </div>
                <h2 className="text-2xl font-bold text-gray-800 mb-2">信息报备</h2>
                <p className="text-gray-500 mb-6">H5 移动端 • 新生信息录入</p>
                <div className="flex items-center text-blue-600 font-semibold group-hover:translate-x-2 transition-transform">
                  进入系统 <ChevronRight className="ml-1" size={20} />
                </div>
              </div>
            </button>

            <button 
              onClick={() => changeMode('ADMIN_APP')}
              className="group relative bg-slate-800 rounded-3xl p-8 shadow-xl hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1 text-left overflow-hidden border border-slate-700"
            >
              <div className="absolute top-0 right-0 bg-slate-700 w-32 h-32 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110 opacity-50"></div>
              <div className="relative z-10">
                <div className="bg-slate-700 w-14 h-14 rounded-2xl flex items-center justify-center mb-6 text-blue-400 group-hover:bg-blue-500 group-hover:text-white transition-colors">
                  <Monitor size={28} />
                </div>
                <h2 className="text-2xl font-bold text-white mb-2">管理后台</h2>
                <p className="text-slate-400 mb-6">Web 端 • 数据管理与分析</p>
                <div className="flex items-center text-blue-400 font-semibold group-hover:translate-x-2 transition-transform">
                  进入后台 <ChevronRight className="ml-1" size={20} />
                </div>
              </div>
            </button>
          </div>

          <p className="text-center text-gray-400 text-sm mt-12">
             请选择对应的入口进入系统
          </p>
        </div>
      </div>
    );
  }

  // --- STUDENT APP FLOW (Information Reporting) ---
  if (mode === 'STUDENT_APP') {
    if (!currentUser) {
      return (
        <div className="min-h-screen bg-school-50 flex flex-col">
          <div className="flex-1 flex flex-col justify-center px-6">
            <div className="w-full max-w-sm mx-auto">
              <div className="text-center mb-10">
                 {/* Customizable Logo Area */}
                <div className="w-24 h-24 mx-auto mb-6 flex items-center justify-center">
                  {settings.logoUrl ? (
                    <img 
                      src={settings.logoUrl} 
                      alt="Logo" 
                      className="w-full h-full object-contain"
                    />
                  ) : (
                     <div className="bg-school-600 w-20 h-20 rounded-2xl rotate-3 shadow-xl flex items-center justify-center">
                       <School className="text-white w-10 h-10" />
                     </div>
                  )}
                </div>

                <h1 className="text-2xl font-bold text-gray-900">信息报备</h1>
                <p className="text-gray-500 text-sm mt-2">请输入姓名和手机号开始录入</p>
              </div>
              <form onSubmit={(e) => handleLogin(e, 'user')} className="space-y-6">

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">姓名</label>
                  <div className="relative">
                    <input
                      type="text"
                      value={username}
                      onChange={(e) => setUsername(e.target.value)}
                      className="w-full pl-10 pr-4 py-4 rounded-xl bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 focus:bg-white transition text-gray-900 placeholder-gray-400"
                      autoComplete="off"
                      placeholder="请输入您的姓名"
                    />
                    <User className="absolute left-3 top-4 text-gray-400" size={20} />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">手机号码</label>
                  <div className="relative">
                    <input
                      type="tel"
                      value={loginPhone}
                      onChange={(e) => setLoginPhone(e.target.value)}
                      className="w-full pl-10 pr-4 py-4 rounded-xl bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 focus:bg-white transition text-gray-900 placeholder-gray-400"
                      maxLength={11}
                      autoComplete="off"
                      placeholder="请输入11位手机号码"
                    />
                    <Smartphone className="absolute left-3 top-4 text-gray-400" size={20} />
                  </div>
                </div>

                {loginError && <p className="text-red-500 text-sm text-center">{loginError}</p>}

                <button type="submit" className="w-full bg-school-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg hover:bg-school-700 transition">
                  进入系统
                </button>
              </form>
            </div>
          </div>
        </div>
      );
    }
    return <StudentForm user={currentUser} onLogout={handleLogout} />;
  }

  // --- ADMIN APP FLOW ---
  if (mode === 'ADMIN_APP') {
    if (!currentUser) {
      return (
        <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden flex flex-col md:flex-row">
            <div className="w-full p-8 md:p-10">
              <div className="text-center mb-8">
                <div className="bg-blue-100 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-4">
                  <Shield className="text-blue-600" size={24} />
                </div>
                <h2 className="text-2xl font-bold text-gray-900">管理后台登录</h2>
                <p className="text-gray-500 text-sm">仅限管理人员访问</p>
              </div>
              <form onSubmit={(e) => handleLogin(e, 'admin')} className="space-y-5">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">管理员账号</label>
                  <input
                    type="text"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    className="w-full px-4 py-3 rounded-lg bg-gray-100 border-0 focus:ring-2 focus:ring-blue-500 focus:bg-white transition text-gray-900 placeholder-gray-400"
                    autoComplete="off"
                    placeholder="请输入管理员账号"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">管理员密码</label>
                  <div className="relative">
                    <input
                      type="password"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="w-full px-4 py-3 rounded-lg bg-gray-100 border-0 focus:ring-2 focus:ring-blue-500 focus:bg-white transition text-gray-900 placeholder-gray-400"
                      autoComplete="new-password"
                      placeholder="请输入密码"
                    />
                    <Lock className="absolute right-3 top-3.5 text-gray-400" size={18} />
                  </div>
                </div>
                {loginError && <div className="p-3 bg-red-50 text-red-600 text-xs rounded-lg">{loginError}</div>}
                <button type="submit" className="w-full bg-slate-900 text-white py-3 rounded-lg font-semibold hover:bg-slate-800 transition">
                  安全登录
                </button>
              </form>
            </div>
          </div>
        </div>
      );
    }
    return <AdminDashboard onLogout={handleLogout} />;
  }

  return null;
};

export default App;

import React, { useState } from 'react';
import { User, CheckCircle, Smartphone, LogOut, PlusCircle, Send, AlertTriangle } from 'lucide-react';
import { saveStudent, isReportingTimeValid } from '../services/dataService';
import { Recruiter } from '../types';

interface Props {
  user: Recruiter;
  onLogout: () => void;
}

const StudentForm: React.FC<Props> = ({ user, onLogout }) => {
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [contactType, setContactType] = useState<'student' | 'parent'>('student');
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // 1. Time Window Validation
    const timeCheck = isReportingTimeValid();
    if (!timeCheck.valid) {
      setError(timeCheck.message || '当前不在报备时间内');
      return;
    }

    // 2. Input Validation
    if (!name || !phone) {
      setError('请填写所有必填项');
      return;
    }

    // 3. Save
    try {
      saveStudent({
        name,
        phoneNumber: phone,
        contactType,
        recruiterId: user.id
      });
      setSubmitted(true);
    } catch (err) {
      setError('提交失败，请重试');
    }
  };

  const handleNext = () => {
    setSubmitted(false);
    setName('');
    setPhone('');
    setContactType('student');
    setError('');
  };

  if (submitted) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-school-50 p-6 animate-in fade-in duration-300">
        <div className="bg-white p-8 rounded-3xl shadow-xl w-full max-w-md text-center">
          <div className="bg-green-100 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6">
             <CheckCircle className="w-10 h-10 text-green-600" />
          </div>
          <h2 className="text-2xl font-bold text-gray-800 mb-2">报备成功!</h2>
          <div className="bg-gray-50 rounded-xl p-4 mb-6 text-left">
            <p className="text-sm text-gray-500 mb-1">已录入学生:</p>
            <p className="text-lg font-bold text-gray-900">{name}</p>
            <div className="mt-2 flex items-center gap-2">
              <span className="text-xs px-2 py-1 bg-blue-100 text-blue-700 rounded">
                {contactType === 'student' ? '学生电话' : '家长电话'}
              </span>
              <span className="text-sm text-gray-600">{phone}</span>
            </div>
          </div>
          <button
            onClick={handleNext}
            className="w-full bg-school-600 text-white py-3.5 rounded-xl font-bold shadow-lg shadow-blue-200 hover:bg-school-700 transition duration-200 flex items-center justify-center gap-2"
          >
            <PlusCircle size={20} /> 报备下一位
          </button>
          <button
            onClick={onLogout}
            className="w-full mt-4 text-gray-500 py-2 text-sm font-medium hover:text-gray-700"
          >
            结束并退出
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-safe">
      {/* Mobile App Header */}
      <div className="bg-school-600 text-white pt-safe sticky top-0 z-30 shadow-md">
        <div className="px-4 py-4 flex justify-between items-center">
          <div>
            <h1 className="text-lg font-bold">信息报备</h1>
            <p className="text-xs text-blue-100 opacity-90">当前操作员: {user.username}</p>
          </div>
          <button 
            onClick={onLogout}
            className="text-xs bg-school-700/50 backdrop-blur-sm px-3 py-1.5 rounded-full hover:bg-school-700 transition flex items-center gap-1 border border-white/20"
          >
            <LogOut size={12} /> 退出
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-md mx-auto p-4">
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-1 h-full bg-school-500"></div>
          <h2 className="text-xl font-bold text-gray-900 mb-6">录入学生信息</h2>

          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Name Input */}
            <div className="space-y-2">
              <label className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                <User size={18} className="text-school-500" /> 学生姓名
              </label>
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="请输入姓名"
                className="w-full px-4 py-3.5 rounded-xl bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 focus:bg-white outline-none transition text-gray-900 placeholder-gray-400"
              />
            </div>

            {/* Phone Input with Type Selection */}
            <div className="space-y-2">
              <label className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                <Smartphone size={18} className="text-school-500" /> 联系电话
              </label>
              <div className="flex gap-2 mb-2">
                <button
                  type="button"
                  onClick={() => setContactType('student')}
                  className={`flex-1 py-2 text-xs font-medium rounded-lg border transition ${contactType === 'student' ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-gray-100 border-transparent text-gray-500'}`}
                >
                  学生本人
                </button>
                <button
                  type="button"
                  onClick={() => setContactType('parent')}
                  className={`flex-1 py-2 text-xs font-medium rounded-lg border transition ${contactType === 'parent' ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-gray-100 border-transparent text-gray-500'}`}
                >
                  家长
                </button>
              </div>
              <input
                type="tel"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                placeholder={contactType === 'student' ? "请输入学生电话" : "请输入家长电话"}
                className="w-full px-4 py-3.5 rounded-xl bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 focus:bg-white outline-none transition text-gray-900 placeholder-gray-400"
              />
            </div>

            {error && (
              <div className="p-3 bg-red-50 text-red-600 text-sm rounded-xl border border-red-100 flex items-start gap-2">
                 <AlertTriangle size={16} className="mt-0.5 shrink-0" /> 
                 <span>{error}</span>
              </div>
            )}

            <button
              type="submit"
              className="w-full bg-school-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg shadow-blue-200 hover:bg-school-700 transition duration-200 flex items-center justify-center gap-2 mt-4"
            >
              <Send size={20} /> 立即报备
            </button>
          </form>
        </div>

        <p className="text-center text-gray-400 text-xs mt-6">
          成都城市建设技工学校 • 报备系统
        </p>
      </div>
    </div>
  );
};

export default StudentForm;

import React, { useEffect, useState } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer 
} from 'recharts';
import { Download, Sparkles, RefreshCw, LogOut, Users, Search, Lock, X, Clock, Plus, Trash2, Check, Image as ImageIcon } from 'lucide-react';
import { 
  getStudents, exportToCSV, verifyAdminPassword, changeAdminPassword, 
  getAppUsers, saveAppUser, deleteAppUser,
  getSystemSettings, saveSystemSettings 
} from '../services/dataService';
import { analyzeRecruitmentData } from '../services/geminiService';
import { Student, AnalysisResult, AppUser, SystemSettings } from '../types';

interface Props {
  onLogout: () => void;
}

type Tab = 'DASHBOARD' | 'USERS' | 'SETTINGS';

const AdminDashboard: React.FC<Props> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<Tab>('DASHBOARD');
  const [students, setStudents] = useState<Student[]>([]);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Password Modal
  const [showPwdModal, setShowPwdModal] = useState(false);
  const [oldPwd, setOldPwd] = useState('');
  const [newPwd, setNewPwd] = useState('');
  const [pwdError, setPwdError] = useState('');
  const [pwdSuccess, setPwdSuccess] = useState('');

  // User Management State
  const [appUsers, setAppUsers] = useState<AppUser[]>([]);
  const [showUserModal, setShowUserModal] = useState(false);
  const [userFormName, setUserFormName] = useState('');
  const [userFormIdCard, setUserFormIdCard] = useState('');
  const [userFormError, setUserFormError] = useState('');

  // Settings State
  const [settings, setSettings] = useState<SystemSettings>({ reportingStartTime: null, reportingEndTime: null, logoUrl: '' });
  const [settingsSaved, setSettingsSaved] = useState(false);

  useEffect(() => {
    loadData();
    loadUsers();
    loadSettings();
  }, []);

  const loadData = () => {
    const data = getStudents();
    setStudents(Array.isArray(data) ? data : []);
  };

  const loadUsers = () => {
    const users = getAppUsers();
    setAppUsers(Array.isArray(users) ? users : []);
  };

  const loadSettings = () => {
    const s = getSystemSettings();
    // Ensure settings object is never null
    setSettings(s || { reportingStartTime: null, reportingEndTime: null, logoUrl: '' });
  };

  // --- Handlers ---

  const handleAnalysis = async () => {
    setAnalyzing(true);
    const result = await analyzeRecruitmentData(students);
    setAnalysis(result);
    setAnalyzing(false);
  };

  const handlePasswordChange = (e: React.FormEvent) => {
    e.preventDefault();
    setPwdError('');
    setPwdSuccess('');

    if (!verifyAdminPassword(oldPwd)) {
      setPwdError('原密码错误');
      return;
    }
    if (newPwd.length < 6) {
      setPwdError('新密码长度不能少于6位');
      return;
    }

    changeAdminPassword(newPwd);
    setPwdSuccess('密码修改成功');
    setTimeout(() => {
      setShowPwdModal(false);
      setOldPwd('');
      setNewPwd('');
      setPwdSuccess('');
    }, 1500);
  };

  const handleAddUser = (e: React.FormEvent) => {
    e.preventDefault();
    setUserFormError('');

    if (!userFormName || !userFormIdCard) {
      setUserFormError('请填写完整信息');
      return;
    }

    try {
      saveAppUser({
        username: userFormName,
        idCard: userFormIdCard,
        status: 'active'
      });
      setShowUserModal(false);
      setUserFormName('');
      setUserFormIdCard('');
      loadUsers();
    } catch (err: any) {
      setUserFormError(err.message || '添加失败');
    }
  };

  const handleDeleteUser = (id: string) => {
    if (confirm('确定要删除该管理员账号吗？删除后该用户将无法登录后台。')) {
      deleteAppUser(id);
      loadUsers();
    }
  };

  const handleSaveSettings = () => {
    saveSystemSettings(settings);
    setSettingsSaved(true);
    setTimeout(() => setSettingsSaved(false), 2000);
  };

  // --- Chart Data ---
  const chartData = React.useMemo(() => {
    if (!Array.isArray(students)) return [];
    const last7Days = [...Array(7)].map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      return {
        date: date.slice(5),
        count: students.filter(s => s.reportTime && s.reportTime.startsWith(date)).length
      };
    });
  }, [students]);

  const filteredStudents = Array.isArray(students) ? students.filter(s => 
    (s.name || '').includes(searchTerm) || 
    (s.phoneNumber || '').includes(searchTerm)
  ) : [];

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col">
      {/* Top Navbar */}
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="bg-school-600 p-2 rounded-lg">
                <Users className="text-white h-6 w-6" />
              </div>
              <div>
                <h1 className="text-xl font-bold text-gray-900">招生管理后台</h1>
                <p className="text-xs text-gray-500">成都城市建设技工学校</p>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <button 
                onClick={() => setShowPwdModal(true)}
                className="flex items-center gap-2 text-sm font-medium text-gray-600 hover:text-school-600 transition"
              >
                <Lock size={16} /> 修改密码
              </button>
              <div className="h-6 w-px bg-gray-200"></div>
              <button
                onClick={onLogout}
                className="flex items-center gap-2 text-sm font-medium text-gray-600 hover:text-red-600 transition"
              >
                <LogOut size={16} /> 退出
              </button>
            </div>
          </div>

          {/* Navigation Tabs */}
          <div className="flex space-x-8 -mb-px overflow-x-auto">
            <button
              onClick={() => setActiveTab('DASHBOARD')}
              className={`pb-4 px-1 border-b-2 font-medium text-sm transition ${activeTab === 'DASHBOARD' ? 'border-school-600 text-school-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
            >
              数据报表
            </button>
            <button
              onClick={() => setActiveTab('USERS')}
              className={`pb-4 px-1 border-b-2 font-medium text-sm transition ${activeTab === 'USERS' ? 'border-school-600 text-school-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
            >
              用户管理
            </button>
            <button
              onClick={() => setActiveTab('SETTINGS')}
              className={`pb-4 px-1 border-b-2 font-medium text-sm transition ${activeTab === 'SETTINGS' ? 'border-school-600 text-school-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
            >
              系统设置
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">

        {/* --- DASHBOARD TAB --- */}
        {activeTab === 'DASHBOARD' && (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
             <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-200">
                <h3 className="text-sm font-medium text-gray-500">总报备人数</h3>
                <div className="mt-2 flex items-baseline gap-2">
                  <span className="text-4xl font-extrabold text-gray-900">{students.length}</span>
                  <span className="text-sm text-gray-500">人</span>
                </div>
                <div className="mt-4">
                  <button 
                    onClick={exportToCSV}
                    className="w-full flex items-center justify-center gap-2 bg-white border border-gray-300 text-gray-700 hover:bg-gray-50 px-4 py-2 rounded-lg text-sm font-medium transition"
                  >
                    <Download size={16} /> 导出报表 (.csv)
                  </button>
                </div>
              </div>

              <div className="bg-gradient-to-br from-school-600 to-school-800 rounded-xl shadow-md p-6 text-white md:col-span-2 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-6 opacity-10">
                  <Sparkles className="w-40 h-40" />
                </div>
                <div className="relative z-10 h-full flex flex-col justify-between">
                  <div className="flex justify-between items-start">
                    <div>
                      <h3 className="text-lg font-bold flex items-center gap-2">
                        <Sparkles className="w-5 h-5 text-yellow-300" /> AI 智能分析
                      </h3>
                      <p className="text-school-100 text-sm mt-1">基于实时数据的招生趋势洞察</p>
                    </div>
                    <button 
                      onClick={handleAnalysis}
                      disabled={analyzing}
                      className={`px-4 py-2 rounded-lg text-sm font-medium backdrop-blur-sm bg-white/20 hover:bg-white/30 transition border border-white/30 ${analyzing ? 'opacity-70 cursor-wait' : ''}`}
                    >
                      {analyzing ? '分析中...' : '生成分析报告'}
                    </button>
                  </div>
                  <div className="mt-4 bg-black/20 rounded-lg p-4 backdrop-blur-md min-h-[100px]">
                    {analysis ? (
                      <div className="space-y-2 text-sm">
                        <p><span className="font-bold text-yellow-300">摘要:</span> {analysis.summary}</p>
                        <p><span className="font-bold text-yellow-300">趋势:</span> {analysis.trend}</p>
                        <p><span className="font-bold text-yellow-300">建议:</span> {analysis.recommendation}</p>
                      </div>
                    ) : (
                      <p className="text-school-200 text-sm italic flex items-center justify-center h-full">点击右上角按钮生成智能分析...</p>
                    )}
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-200">
              <h3 className="text-lg font-bold text-gray-800 mb-6">近7日报名趋势</h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="date" tick={{fontSize: 12}} />
                    <YAxis allowDecimals={false} tick={{fontSize: 12}} />
                    <RechartsTooltip contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} />
                    <Bar name="报备人数" dataKey="count" fill="#2563eb" radius={[4, 4, 0, 0]} barSize={40} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden flex flex-col">
              <div className="p-4 border-b border-gray-200 flex flex-col sm:flex-row justify-between items-center gap-4">
                <div className="flex items-center gap-2">
                   <h3 className="text-lg font-bold text-gray-800">详细报备列表</h3>
                   <button onClick={loadData} className="text-gray-400 hover:text-school-600"><RefreshCw size={16} /></button>
                </div>
                <div className="relative w-full sm:w-64">
                  <input 
                    type="text" 
                    placeholder="搜索姓名/电话..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full pl-10 pr-4 py-2 bg-gray-100 border-0 rounded-lg focus:ring-2 focus:ring-school-500 focus:bg-white transition outline-none text-sm text-gray-900 placeholder-gray-400"
                  />
                  <Search className="absolute left-3 top-2.5 text-gray-400 w-4 h-4" />
                </div>
              </div>

              <div className="overflow-x-auto custom-scrollbar">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">姓名</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">联系电话</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">归属</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">报备时间</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">填报人</th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {filteredStudents.length > 0 ? (
                      filteredStudents.map((student) => (
                        <tr key={student.id} className="hover:bg-gray-50 transition">
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{student.name}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{student.phoneNumber}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm">
                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${student.contactType === 'student' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>
                              {student.contactType === 'student' ? '学生' : '家长'}
                            </span>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{new Date(student.reportTime).toLocaleString()}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{student.recruiterId}</td>
                        </tr>
                      ))
                    ) : (
                      <tr><td colSpan={5} className="px-6 py-12 text-center text-sm text-gray-500">没有找到匹配的数据</td></tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {/* --- USERS TAB (NOW ADMIN MANAGEMENT) --- */}
        {activeTab === 'USERS' && (
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300">
             <div className="p-6 border-b border-gray-200 flex justify-between items-center">
               <div>
                 <h2 className="text-lg font-bold text-gray-900">用户管理</h2>
                 <p className="text-sm text-gray-500">添加其他管理员账号 (子管理员)</p>
               </div>
               <button 
                 onClick={() => setShowUserModal(true)}
                 className="flex items-center gap-2 bg-school-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-school-700 transition"
               >
                 <Plus size={16} /> 添加管理员
               </button>
             </div>

             <table className="min-w-full divide-y divide-gray-200">
               <thead className="bg-gray-50">
                 <tr>
                   <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">姓名 (登录账号)</th>
                   <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">身份证号 (登录密码)</th>
                   <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">创建时间</th>
                   <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">状态</th>
                   <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">操作</th>
                 </tr>
               </thead>
               <tbody className="bg-white divide-y divide-gray-200">
                 {appUsers.length > 0 ? (
                   appUsers.map(user => (
                     <tr key={user.id} className="hover:bg-gray-50">
                       <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{user.username}</td>
                       <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 font-mono">{user.idCard}</td>
                       <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{new Date(user.createdAt).toLocaleDateString()}</td>
                       <td className="px-6 py-4 whitespace-nowrap">
                         <span className={`px-2 py-1 rounded-full text-xs font-medium ${user.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                           {user.status === 'active' ? '正常' : '禁用'}
                         </span>
                       </td>
                       <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                         <button 
                           onClick={() => handleDeleteUser(user.id)}
                           className="text-red-600 hover:text-red-900 ml-4 flex items-center gap-1 float-right"
                         >
                           <Trash2 size={16} /> 删除
                         </button>
                       </td>
                     </tr>
                   ))
                 ) : (
                   <tr><td colSpan={5} className="px-6 py-12 text-center text-sm text-gray-500">暂无子管理员，请点击右上角添加</td></tr>
                 )}
               </tbody>
             </table>
          </div>
        )}

        {/* --- SETTINGS TAB --- */}
        {activeTab === 'SETTINGS' && (
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-8 animate-in fade-in slide-in-from-bottom-2 duration-300">
             <div className="max-w-2xl space-y-8">

               {/* Time Settings */}
               <div>
                 <h2 className="text-xl font-bold text-gray-900 mb-6 flex items-center gap-2">
                   <Clock className="text-school-600" /> 报备时间设置
                 </h2>
                 <div className="bg-blue-50 border border-blue-100 rounded-lg p-4 mb-6 text-sm text-blue-800">
                   <p>设置报备系统的开放时间窗口。如果在该时间段之外，移动端将无法提交数据。</p>
                   <p className="mt-1 font-medium">留空则表示不限制时间。</p>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div>
                     <label className="block text-sm font-medium text-gray-700 mb-2">开始时间</label>
                     <input 
                       type="datetime-local" 
                       className="w-full px-4 py-3 rounded-lg bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 text-gray-900"
                       value={settings?.reportingStartTime || ''}
                       onChange={(e) => setSettings({...settings, reportingStartTime: e.target.value})}
                     />
                   </div>
                   <div>
                     <label className="block text-sm font-medium text-gray-700 mb-2">截止时间</label>
                     <input 
                       type="datetime-local" 
                       className="w-full px-4 py-3 rounded-lg bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 text-gray-900"
                       value={settings?.reportingEndTime || ''}
                       onChange={(e) => setSettings({...settings, reportingEndTime: e.target.value})}
                     />
                   </div>
                 </div>
               </div>

               <hr className="border-gray-100" />

               {/* Logo Settings */}
               <div>
                 <h2 className="text-xl font-bold text-gray-900 mb-6 flex items-center gap-2">
                   <ImageIcon className="text-school-600" /> 首页 Logo 设置
                 </h2>
                 <div>
                   <label className="block text-sm font-medium text-gray-700 mb-2">自定义 Logo 图片链接 (URL)</label>
                   <input 
                     type="text" 
                     className="w-full px-4 py-3 rounded-lg bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 text-gray-900 placeholder-gray-400"
                     value={settings?.logoUrl || ''}
                     onChange={(e) => setSettings({...settings, logoUrl: e.target.value})}
                     placeholder="例如: https://example.com/logo.png"
                   />
                   <p className="text-xs text-gray-500 mt-2">
                     请输入图片的完整 URL 地址。如果留空，将显示默认学校图标。
                   </p>
                 </div>
               </div>

               <button 
                 onClick={handleSaveSettings}
                 className="flex items-center gap-2 bg-school-600 text-white px-6 py-3 rounded-xl font-medium hover:bg-school-700 transition"
               >
                 {settingsSaved ? <Check size={20} /> : null}
                 {settingsSaved ? '已保存设置' : '保存设置'}
               </button>
             </div>
          </div>
        )}
