  const [oldPwd, setOldPwd] = useState('');
  const [newPwd, setNewPwd] = useState('');
  const [pwdError, setPwdError] = useState('');
  const [pwdSuccess, setPwdSuccess] = useState('');

  // User Management State
  const [appUsers, setAppUsers] = useState<AppUser[]>([]);
  const [showUserModal, setShowUserModal] = useState(false);
  const [userFormName, setUserFormName] = useState('');
  const [userFormIdCard, setUserFormIdCard] = useState('');
  const [userFormError, setUserFormError] = useState('');

  // Settings State
  const [settings, setSettings] = useState<SystemSettings>({ reportingStartTime: null, reportingEndTime: null, logoUrl: '' });
  const [settingsSaved, setSettingsSaved] = useState(false);

  useEffect(() => {
    loadData();
    loadUsers();
    loadSettings();
  }, []);

  const loadData = () => {
    const data = getStudents();
    setStudents(Array.isArray(data) ? data : []);
  };

  const loadUsers = () => {
    const users = getAppUsers();
    setAppUsers(Array.isArray(users) ? users : []);
  };

  const loadSettings = () => {
    const s = getSystemSettings();
    // Ensure settings object is never null
    setSettings(s || { reportingStartTime: null, reportingEndTime: null, logoUrl: '' });
  };

  // --- Handlers ---

  const handleAnalysis = async () => {
    setAnalyzing(true);
    const result = await analyzeRecruitmentData(students);
    setAnalysis(result);
    setAnalyzing(false);
  };

  const handlePasswordChange = (e: React.FormEvent) => {
    e.preventDefault();
    setPwdError('');
    setPwdSuccess('');

    if (!verifyAdminPassword(oldPwd)) {
      setPwdError('原密码错误');
      return;
    }
    if (newPwd.length < 6) {
      setPwdError('新密码长度不能少于6位');
      return;
    }

    changeAdminPassword(newPwd);
    setPwdSuccess('密码修改成功');
    setTimeout(() => {
      setShowPwdModal(false);
      setOldPwd('');
      setNewPwd('');
      setPwdSuccess('');
    }, 1500);
  };

  const handleAddUser = (e: React.FormEvent) => {
    e.preventDefault();
    setUserFormError('');

    if (!userFormName || !userFormIdCard) {
      setUserFormError('请填写完整信息');
      return;
    }

    try {
      saveAppUser({
        username: userFormName,
        idCard: userFormIdCard,
        status: 'active'
      });
      setShowUserModal(false);
      setUserFormName('');
      setUserFormIdCard('');
      loadUsers();
    } catch (err: any) {
      setUserFormError(err.message || '添加失败');
    }
  };

  const handleDeleteUser = (id: string) => {
    if (confirm('确定要删除该管理员账号吗？删除后该用户将无法登录后台。')) {
      deleteAppUser(id);
      loadUsers();
    }
  };

  const handleSaveSettings = () => {
    saveSystemSettings(settings);
    setSettingsSaved(true);
    setTimeout(() => setSettingsSaved(false), 2000);
  };

  // --- Chart Data ---
  const chartData = React.useMemo(() => {
    if (!Array.isArray(students)) return [];
    const last7Days = [...Array(7)].map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      return {
        date: date.slice(5),
        count: students.filter(s => s.reportTime && s.reportTime.startsWith(date)).length
      };
    });
  }, [students]);

  const filteredStudents = Array.isArray(students) ? students.filter(s => 
    (s.name || '').includes(searchTerm) || 
    (s.phoneNumber || '').includes(searchTerm)
  ) : [];

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col">
      {/* Top Navbar */}
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <img src={DEFAULT_LOGO} alt="Logo" className="h-10 w-10 object-contain" />
              <div>
                <h1 className="text-xl font-bold text-gray-900">招生管理后台</h1>
                <p className="text-xs text-gray-500">成都城市建设技工学校</p>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <button 
                onClick={() => setShowPwdModal(true)}
                className="flex items-center gap-2 text-sm font-medium text-gray-600 hover:text-school-600 transition"
              >
                <Lock size={16} /> 修改密码
              </button>
              <div className="h-6 w-px bg-gray-200"></div>
              <button
                onClick={onLogout}
                className="flex items-center gap-2 text-sm font-medium text-gray-600 hover:text-red-600 transition"
              >
                <LogOut size={16} /> 退出
              </button>
            </div>
          </div>

          {/* Navigation Tabs */}
          <div className="flex space-x-8 -mb-px overflow-x-auto">
            <button
              onClick={() => setActiveTab('DASHBOARD')}
              className={`pb-4 px-1 border-b-2 font-medium text-sm transition ${activeTab === 'DASHBOARD' ? 'border-school-600 text-school-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
            >
              数据报表
            </button>
            <button
              onClick={() => setActiveTab('USERS')}
              className={`pb-4 px-1 border-b-2 font-medium text-sm transition ${activeTab === 'USERS' ? 'border-school-600 text-school-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
            >
              用户管理
            </button>
            <button
              onClick={() => setActiveTab('SETTINGS')}
              className={`pb-4 px-1 border-b-2 font-medium text-sm transition ${activeTab === 'SETTINGS' ? 'border-school-600 text-school-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
            >
              系统设置
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">

        {/* --- DASHBOARD TAB --- */}
        {activeTab === 'DASHBOARD' && (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
             <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-200">
                <h3 className="text-sm font-medium text-gray-500">总报备人数</h3>
                <div className="mt-2 flex items-baseline gap-2">
                  <span className="text-4xl font-extrabold text-gray-900">{students.length}</span>
                  <span className="text-sm text-gray-500">人</span>
                </div>
                <div className="mt-4">
                  <button 
                    onClick={exportToCSV}
                    className="w-full flex items-center justify-center gap-2 bg-white border border-gray-300 text-gray-700 hover:bg-gray-50 px-4 py-2 rounded-lg text-sm font-medium transition"
                  >
                    <Download size={16} /> 导出报表 (.csv)
                  </button>
                </div>
              </div>

              <div className="bg-gradient-to-br from-school-600 to-school-800 rounded-xl shadow-md p-6 text-white md:col-span-2 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-6 opacity-10">
                  <Sparkles className="w-40 h-40" />
                </div>
                <div className="relative z-10 h-full flex flex-col justify-between">
                  <div className="flex justify-between items-start">
                    <div>
                      <h3 className="text-lg font-bold flex items-center gap-2">
                        <Sparkles className="w-5 h-5 text-yellow-300" /> AI 智能分析
                      </h3>
                      <p className="text-school-100 text-sm mt-1">基于实时数据的招生趋势洞察</p>
                    </div>
                    <button 
                      onClick={handleAnalysis}
                      disabled={analyzing}
                      className={`px-4 py-2 rounded-lg text-sm font-medium backdrop-blur-sm bg-white/20 hover:bg-white/30 transition border border-white/30 ${analyzing ? 'opacity-70 cursor-wait' : ''}`}
                    >
                      {analyzing ? '分析中...' : '生成分析报告'}
                    </button>
                  </div>
                  <div className="mt-4 bg-black/20 rounded-lg p-4 backdrop-blur-md min-h-[100px]">
                    {analysis ? (
                      <div className="space-y-2 text-sm">
                        <p><span className="font-bold text-yellow-300">摘要:</span> {analysis.summary}</p>
                        <p><span className="font-bold text-yellow-300">趋势:</span> {analysis.trend}</p>
                        <p><span className="font-bold text-yellow-300">建议:</span> {analysis.recommendation}</p>
                      </div>
                    ) : (
                      <p className="text-school-200 text-sm italic flex items-center justify-center h-full">点击右上角按钮生成智能分析...</p>
                    )}
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-200">
              <h3 className="text-lg font-bold text-gray-800 mb-6">近7日报名趋势</h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="date" tick={{fontSize: 12}} />
                    <YAxis allowDecimals={false} tick={{fontSize: 12}} />
                    <RechartsTooltip contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} />
                    <Bar name="报备人数" dataKey="count" fill="#2563eb" radius={[4, 4, 0, 0]} barSize={40} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden flex flex-col">
              <div className="p-4 border-b border-gray-200 flex flex-col sm:flex-row justify-between items-center gap-4">
                <div className="flex items-center gap-2">
                   <h3 className="text-lg font-bold text-gray-800">详细报备列表</h3>
                   <button onClick={loadData} className="text-gray-400 hover:text-school-600"><RefreshCw size={16} /></button>
                </div>
                <div className="relative w-full sm:w-64">
                  <input 
                    type="text" 
                    placeholder="搜索姓名/电话..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full pl-10 pr-4 py-2 bg-gray-100 border-0 rounded-lg focus:ring-2 focus:ring-school-500 focus:bg-white transition outline-none text-sm text-gray-900 placeholder-gray-400"
                  />
                  <Search className="absolute left-3 top-2.5 text-gray-400 w-4 h-4" />
                </div>
              </div>

              <div className="overflow-x-auto custom-scrollbar">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">姓名</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">联系电话</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">归属</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">报备时间</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">填报人</th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {filteredStudents.length > 0 ? (
                      filteredStudents.map((student) => (
                        <tr key={student.id} className="hover:bg-gray-50 transition">
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{student.name}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{student.phoneNumber}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm">
                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${student.contactType === 'student' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>
                              {student.contactType === 'student' ? '学生' : '家长'}
                            </span>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{new Date(student.reportTime).toLocaleString()}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{student.recruiterId}</td>
                        </tr>
                      ))
                    ) : (
                      <tr><td colSpan={5} className="px-6 py-12 text-center text-sm text-gray-500">没有找到匹配的数据</td></tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {/* --- USERS TAB (NOW ADMIN MANAGEMENT) --- */}
        {activeTab === 'USERS' && (
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300">
             <div className="p-6 border-b border-gray-200 flex justify-between items-center">
               <div>
                 <h2 className="text-lg font-bold text-gray-900">用户管理</h2>
                 <p className="text-sm text-gray-500">添加其他管理员账号 (子管理员)</p>
               </div>
               <button 
                 onClick={() => setShowUserModal(true)}
                 className="flex items-center gap-2 bg-school-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-school-700 transition"
               >
                 <Plus size={16} /> 添加管理员
               </button>
             </div>

             <table className="min-w-full divide-y divide-gray-200">
               <thead className="bg-gray-50">
                 <tr>
                   <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">姓名 (登录账号)</th>
                   <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">身份证号 (登录密码)</th>
                   <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">创建时间</th>
                   <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">状态</th>
                   <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">操作</th>
                 </tr>
               </thead>
               <tbody className="bg-white divide-y divide-gray-200">
                 {appUsers.length > 0 ? (
                   appUsers.map(user => (
                     <tr key={user.id} className="hover:bg-gray-50">
                       <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{user.username}</td>
                       <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 font-mono">{user.idCard}</td>
                       <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{new Date(user.createdAt).toLocaleDateString()}</td>
                       <td className="px-6 py-4 whitespace-nowrap">
                         <span className={`px-2 py-1 rounded-full text-xs font-medium ${user.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                           {user.status === 'active' ? '正常' : '禁用'}
                         </span>
                       </td>
                       <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                         <button 
                           onClick={() => handleDeleteUser(user.id)}
                           className="text-red-600 hover:text-red-900 ml-4 flex items-center gap-1 float-right"
                         >
                           <Trash2 size={16} /> 删除
                         </button>
                       </td>
                     </tr>
                   ))
                 ) : (
                   <tr><td colSpan={5} className="px-6 py-12 text-center text-sm text-gray-500">暂无子管理员，请点击右上角添加</td></tr>
                 )}
               </tbody>
             </table>
          </div>
        )}

        {/* --- SETTINGS TAB --- */}
        {activeTab === 'SETTINGS' && (
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-8 animate-in fade-in slide-in-from-bottom-2 duration-300">
             <div className="max-w-2xl space-y-8">

               {/* Time Settings */}
               <div>
                 <h2 className="text-xl font-bold text-gray-900 mb-6 flex items-center gap-2">
                   <Clock className="text-school-600" /> 报备时间设置
                 </h2>
                 <div className="bg-blue-50 border border-blue-100 rounded-lg p-4 mb-6 text-sm text-blue-800">
                   <p>设置报备系统的开放时间窗口。如果在该时间段之外，移动端将无法提交数据。</p>
                   <p className="mt-1 font-medium">留空则表示不限制时间。</p>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div>
                     <label className="block text-sm font-medium text-gray-700 mb-2">开始时间</label>
                     <input 
                       type="datetime-local" 
                       className="w-full px-4 py-3 rounded-lg bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 text-gray-900"
                       value={settings?.reportingStartTime || ''}
                       onChange={(e) => setSettings({...settings, reportingStartTime: e.target.value})}
                     />
                   </div>
                   <div>
                     <label className="block text-sm font-medium text-gray-700 mb-2">截止时间</label>
                     <input 
                       type="datetime-local" 
                       className="w-full px-4 py-3 rounded-lg bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 text-gray-900"
                       value={settings?.reportingEndTime || ''}
                       onChange={(e) => setSettings({...settings, reportingEndTime: e.target.value})}
                     />
                   </div>
                 </div>
               </div>

               <hr className="border-gray-100" />

               {/* Logo Settings */}
               <div>
                 <h2 className="text-xl font-bold text-gray-900 mb-6 flex items-center gap-2">
                   <ImageIcon className="text-school-600" /> 首页 Logo 设置
                 </h2>
                 <div>
                   <label className="block text-sm font-medium text-gray-700 mb-2">自定义 Logo 图片链接 (URL)</label>
                   <input 
                     type="text" 
                     className="w-full px-4 py-3 rounded-lg bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 text-gray-900 placeholder-gray-400"
                     value={settings?.logoUrl || ''}
                     onChange={(e) => setSettings({...settings, logoUrl: e.target.value})}
                     placeholder="例如: https://example.com/logo.png"
                   />
                   <p className="text-xs text-gray-500 mt-2">
                     请输入图片的完整 URL 地址。如果留空，将显示默认学校图标。
                   </p>
                 </div>
               </div>

               <button 
                 onClick={handleSaveSettings}
                 className="flex items-center gap-2 bg-school-600 text-white px-6 py-3 rounded-xl font-medium hover:bg-school-700 transition"
               >
                 {settingsSaved ? <Check size={20} /> : null}
                 {settingsSaved ? '已保存设置' : '保存设置'}
               </button>
             </div>
          </div>
        )}
      </main>

      {/* --- MODALS --- */}

      {/* Password Modal */}
      {showPwdModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm p-6 relative">
            <button onClick={() => setShowPwdModal(false)} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"><X size={20} /></button>
            <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center gap-2"><Lock size={18} className="text-school-600" /> 修改管理员密码</h3>
            <form onSubmit={handlePasswordChange} className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">当前密码</label>
                <input type="password" value={oldPwd} onChange={(e) => setOldPwd(e.target.value)} className="w-full px-3 py-2 bg-gray-100 border-0 rounded-lg text-gray-900" />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">新密码</label>
                <input type="password" value={newPwd} onChange={(e) => setNewPwd(e.target.value)} className="w-full px-3 py-2 bg-gray-100 border-0 rounded-lg text-gray-900" />
              </div>
              {pwdError && <p className="text-red-500 text-xs">{pwdError}</p>}
              {pwdSuccess && <p className="text-green-500 text-xs">{pwdSuccess}</p>}
              <button type="submit" className="w-full bg-school-600 text-white py-2.5 rounded-lg font-medium hover:bg-school-700 transition">确认修改</button>
            </form>
          </div>
        </div>
      )}

      {/* Add User Modal */}
      {showUserModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm p-6 relative">
            <button onClick={() => setShowUserModal(false)} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"><X size={20} /></button>
            <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center gap-2"><Plus size={18} className="text-school-600" /> 添加子管理员</h3>
            <form onSubmit={handleAddUser} className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">姓名</label>
                <input 
                  type="text" 
                  value={userFormName} 
                  onChange={(e) => setUserFormName(e.target.value)} 
                  className="w-full px-3 py-2 bg-gray-100 border-0 rounded-lg text-gray-900" 
                  placeholder="如: 李四"
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">身份证号 (用于登录密码)</label>
                <input 
                  type="text" 
                  value={userFormIdCard} 
                  onChange={(e) => setUserFormIdCard(e.target.value)} 
                  className="w-full px-3 py-2 bg-gray-100 border-0 rounded-lg text-gray-900 font-mono"
                  placeholder="18位身份证号"
                />
              </div>
              {userFormError && <p className="text-red-500 text-xs">{userFormError}</p>}
              <button type="submit" className="w-full bg-school-600 text-white py-2.5 rounded-lg font-medium hover:bg-school-700 transition">确认添加</button>
            </form>
          </div>
        </div>
      )}

    </div>
  );
};

export default AdminDashboard;

import React, { useEffect, useState, useRef } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer 
} from 'recharts';
import { Download, Sparkles, RefreshCw, LogOut, Users, Search, Lock, X, Clock, Plus, Trash2, Check, Image as ImageIcon, Upload } from 'lucide-react';
import { 
  getStudents, exportToCSV, verifyAdminPassword, changeAdminPassword, 
  getAppUsers, saveAppUser, deleteAppUser,
  getSystemSettings, saveSystemSettings 
} from '../services/dataService';
import { analyzeRecruitmentData } from '../services/geminiService';
import { Student, AnalysisResult, AppUser, SystemSettings } from '../types';

interface Props {
  onLogout: () => void;
}

type Tab = 'DASHBOARD' | 'USERS' | 'SETTINGS';

const DEFAULT_LOGO = "https://aistudiocdn.com/uploads/image-1065e8a7-331e-4530-9781-c7d58a5f57cc.png";

const AdminDashboard: React.FC<Props> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<Tab>('DASHBOARD');
  const [students, setStudents] = useState<Student[]>([]);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Password Modal
  const [showPwdModal, setShowPwdModal] = useState(false);
  const [oldPwd, setOldPwd] = useState('');
  const [newPwd, setNewPwd] = useState('');
  const [pwdError, setPwdError] = useState('');
  const [pwdSuccess, setPwdSuccess] = useState('');

  // User Management State
  const [appUsers, setAppUsers] = useState<AppUser[]>([]);
  const [showUserModal, setShowUserModal] = useState(false);
  const [userFormName, setUserFormName] = useState('');
  const [userFormIdCard, setUserFormIdCard] = useState('');
  const [userFormError, setUserFormError] = useState('');

  // Settings State
  const [settings, setSettings] = useState<SystemSettings>({ reportingStartTime: null, reportingEndTime: null, logoUrl: '' });
  const [settingsSaved, setSettingsSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    loadData();
    loadUsers();
    loadSettings();
  }, []);

  const loadData = () => {
    const data = getStudents();
    setStudents(Array.isArray(data) ? data : []);
  };

  const loadUsers = () => {
    const users = getAppUsers();
    setAppUsers(Array.isArray(users) ? users : []);
  };

  const loadSettings = () => {
    const s = getSystemSettings();
    // Ensure settings object is never null
    setSettings(s || { reportingStartTime: null, reportingEndTime: null, logoUrl: '' });
  };

  // --- Handlers ---

  const handleAnalysis = async () => {
    setAnalyzing(true);
    const result = await analyzeRecruitmentData(students);
    setAnalysis(result);
    setAnalyzing(false);
  };

  const handlePasswordChange = (e: React.FormEvent) => {
    e.preventDefault();
    setPwdError('');
    setPwdSuccess('');

    if (!verifyAdminPassword(oldPwd)) {
      setPwdError('原密码错误');
      return;
    }
    if (newPwd.length < 6) {
      setPwdError('新密码长度不能少于6位');
      return;
    }

    changeAdminPassword(newPwd);
    setPwdSuccess('密码修改成功');
    setTimeout(() => {
      setShowPwdModal(false);
      setOldPwd('');
      setNewPwd('');
      setPwdSuccess('');
    }, 1500);
  };

  const handleAddUser = (e: React.FormEvent) => {
    e.preventDefault();
    setUserFormError('');

    if (!userFormName || !userFormIdCard) {
      setUserFormError('请填写完整信息');
      return;
    }

    try {
      saveAppUser({
        username: userFormName,
        idCard: userFormIdCard,
        status: 'active'
      });
      setShowUserModal(false);
      setUserFormName('');
      setUserFormIdCard('');
      loadUsers();
    } catch (err: any) {
      setUserFormError(err.message || '添加失败');
    }
  };

  const handleDeleteUser = (id: string) => {
    if (confirm('确定要删除该管理员账号吗？删除后该用户将无法登录后台。')) {
      deleteAppUser(id);
      loadUsers();
    }
  };

  const handleSaveSettings = () => {
    saveSystemSettings(settings);
    setSettingsSaved(true);
    setTimeout(() => setSettingsSaved(false), 2000);
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Limit file size to 1MB to avoid filling up LocalStorage
    if (file.size > 1024 * 1024) {
      alert("为了保证系统性能，图片大小不能超过 1MB。");
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      setSettings(prev => ({ ...prev, logoUrl: base64String }));
    };
    reader.readAsDataURL(file);
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
  };

  // --- Chart Data ---
  const chartData = React.useMemo(() => {
    if (!Array.isArray(students)) return [];
    const last7Days = [...Array(7)].map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      return {
        date: date.slice(5),
        count: students.filter(s => s.reportTime && s.reportTime.startsWith(date)).length
      };
    });
  }, [students]);

  const filteredStudents = Array.isArray(students) ? students.filter(s => 
    (s.name || '').includes(searchTerm) || 
    (s.phoneNumber || '').includes(searchTerm)
  ) : [];

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col">
      {/* Top Navbar */}
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <img src={settings.logoUrl || DEFAULT_LOGO} alt="Logo" className="h-10 w-10 object-contain" />
              <div>
                <h1 className="text-xl font-bold text-gray-900">招生管理后台</h1>
                <p className="text-xs text-gray-500">成都城市建设技工学校</p>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <button 
                onClick={() => setShowPwdModal(true)}
                className="flex items-center gap-2 text-sm font-medium text-gray-600 hover:text-school-600 transition"
              >
                <Lock size={16} /> 修改密码
              </button>
              <div className="h-6 w-px bg-gray-200"></div>
              <button
                onClick={onLogout}
                className="flex items-center gap-2 text-sm font-medium text-gray-600 hover:text-red-600 transition"
              >
                <LogOut size={16} /> 退出
              </button>
            </div>
          </div>

          {/* Navigation Tabs */}
          <div className="flex space-x-8 -mb-px overflow-x-auto">
            <button
              onClick={() => setActiveTab('DASHBOARD')}
              className={`pb-4 px-1 border-b-2 font-medium text-sm transition ${activeTab === 'DASHBOARD' ? 'border-school-600 text-school-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
            >
              数据报表
            </button>
            <button
              onClick={() => setActiveTab('USERS')}
              className={`pb-4 px-1 border-b-2 font-medium text-sm transition ${activeTab === 'USERS' ? 'border-school-600 text-school-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
            >
              用户管理
            </button>
            <button
              onClick={() => setActiveTab('SETTINGS')}
              className={`pb-4 px-1 border-b-2 font-medium text-sm transition ${activeTab === 'SETTINGS' ? 'border-school-600 text-school-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
            >
              系统设置
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">

        {/* --- DASHBOARD TAB --- */}
        {activeTab === 'DASHBOARD' && (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
             <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-200">
                <h3 className="text-sm font-medium text-gray-500">总报备人数</h3>
                <div className="mt-2 flex items-baseline gap-2">
                  <span className="text-4xl font-extrabold text-gray-900">{students.length}</span>
                  <span className="text-sm text-gray-500">人</span>
                </div>
                <div className="mt-4">
                  <button 
                    onClick={exportToCSV}
                    className="w-full flex items-center justify-center gap-2 bg-white border border-gray-300 text-gray-700 hover:bg-gray-50 px-4 py-2 rounded-lg text-sm font-medium transition"
                  >
                    <Download size={16} /> 导出报表 (.csv)
                  </button>
                </div>
              </div>

              <div className="bg-gradient-to-br from-school-600 to-school-800 rounded-xl shadow-md p-6 text-white md:col-span-2 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-6 opacity-10">
                  <Sparkles className="w-40 h-40" />
                </div>
                <div className="relative z-10 h-full flex flex-col justify-between">
                  <div className="flex justify-between items-start">
                    <div>
                      <h3 className="text-lg font-bold flex items-center gap-2">
                        <Sparkles className="w-5 h-5 text-yellow-300" /> AI 智能分析
                      </h3>
                      <p className="text-school-100 text-sm mt-1">基于实时数据的招生趋势洞察</p>
                    </div>
                    <button 
                      onClick={handleAnalysis}
                      disabled={analyzing}
                      className={`px-4 py-2 rounded-lg text-sm font-medium backdrop-blur-sm bg-white/20 hover:bg-white/30 transition border border-white/30 ${analyzing ? 'opacity-70 cursor-wait' : ''}`}
                    >
                      {analyzing ? '分析中...' : '生成分析报告'}
                    </button>
                  </div>
                  <div className="mt-4 bg-black/20 rounded-lg p-4 backdrop-blur-md min-h-[100px]">
                    {analysis ? (
                      <div className="space-y-2 text-sm">
                        <p><span className="font-bold text-yellow-300">摘要:</span> {analysis.summary}</p>
                        <p><span className="font-bold text-yellow-300">趋势:</span> {analysis.trend}</p>
                        <p><span className="font-bold text-yellow-300">建议:</span> {analysis.recommendation}</p>
                      </div>
                    ) : (
                      <p className="text-school-200 text-sm italic flex items-center justify-center h-full">点击右上角按钮生成智能分析...</p>
                    )}
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-200">
              <h3 className="text-lg font-bold text-gray-800 mb-6">近7日报名趋势</h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                    <XAxis dataKey="date" tick={{fontSize: 12}} />
                    <YAxis allowDecimals={false} tick={{fontSize: 12}} />
                    <RechartsTooltip contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} />
                    <Bar name="报备人数" dataKey="count" fill="#2563eb" radius={[4, 4, 0, 0]} barSize={40} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden flex flex-col">
              <div className="p-4 border-b border-gray-200 flex flex-col sm:flex-row justify-between items-center gap-4">
                <div className="flex items-center gap-2">
                   <h3 className="text-lg font-bold text-gray-800">详细报备列表</h3>
                   <button onClick={loadData} className="text-gray-400 hover:text-school-600"><RefreshCw size={16} /></button>
                </div>
                <div className="relative w-full sm:w-64">
                  <input 
                    type="text" 
                    placeholder="搜索姓名/电话..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full pl-10 pr-4 py-2 bg-gray-100 border-0 rounded-lg focus:ring-2 focus:ring-school-500 focus:bg-white transition outline-none text-sm text-gray-900 placeholder-gray-400"
                  />
                  <Search className="absolute left-3 top-2.5 text-gray-400 w-4 h-4" />
                </div>
              </div>

              <div className="overflow-x-auto custom-scrollbar">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">姓名</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">联系电话</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">归属</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">报备时间</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">填报人</th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {filteredStudents.length > 0 ? (
                      filteredStudents.map((student) => (
                        <tr key={student.id} className="hover:bg-gray-50 transition">
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{student.name}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{student.phoneNumber}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm">
                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${student.contactType === 'student' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>
                              {student.contactType === 'student' ? '学生' : '家长'}
                            </span>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{new Date(student.reportTime).toLocaleString()}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{student.recruiterId}</td>
                        </tr>
                      ))
                    ) : (
                      <tr><td colSpan={5} className="px-6 py-12 text-center text-sm text-gray-500">没有找到匹配的数据</td></tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {/* --- USERS TAB (NOW ADMIN MANAGEMENT) --- */}
        {activeTab === 'USERS' && (
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300">
             <div className="p-6 border-b border-gray-200 flex justify-between items-center">
               <div>
                 <h2 className="text-lg font-bold text-gray-900">用户管理</h2>
                 <p className="text-sm text-gray-500">添加其他管理员账号 (子管理员)</p>
               </div>
               <button 
                 onClick={() => setShowUserModal(true)}
                 className="flex items-center gap-2 bg-school-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-school-700 transition"
               >
                 <Plus size={16} /> 添加管理员
               </button>
             </div>

             <table className="min-w-full divide-y divide-gray-200">
               <thead className="bg-gray-50">
                 <tr>
                   <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">姓名 (登录账号)</th>
                   <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">身份证号 (登录密码)</th>
                   <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">创建时间</th>
                   <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">状态</th>
                   <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">操作</th>
                 </tr>
               </thead>
               <tbody className="bg-white divide-y divide-gray-200">
                 {appUsers.length > 0 ? (
                   appUsers.map(user => (
                     <tr key={user.id} className="hover:bg-gray-50">
                       <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{user.username}</td>
                       <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 font-mono">{user.idCard}</td>
                       <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{new Date(user.createdAt).toLocaleDateString()}</td>
                       <td className="px-6 py-4 whitespace-nowrap">
                         <span className={`px-2 py-1 rounded-full text-xs font-medium ${user.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                           {user.status === 'active' ? '正常' : '禁用'}
                         </span>
                       </td>
                       <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                         <button 
                           onClick={() => handleDeleteUser(user.id)}
                           className="text-red-600 hover:text-red-900 ml-4 flex items-center gap-1 float-right"
                         >
                           <Trash2 size={16} /> 删除
                         </button>
                       </td>
                     </tr>
                   ))
                 ) : (
                   <tr><td colSpan={5} className="px-6 py-12 text-center text-sm text-gray-500">暂无子管理员，请点击右上角添加</td></tr>
                 )}
               </tbody>
             </table>
          </div>
        )}

        {/* --- SETTINGS TAB --- */}
        {activeTab === 'SETTINGS' && (
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-8 animate-in fade-in slide-in-from-bottom-2 duration-300">
             <div className="max-w-2xl space-y-8">

               {/* Time Settings */}
               <div>
                 <h2 className="text-xl font-bold text-gray-900 mb-6 flex items-center gap-2">
                   <Clock className="text-school-600" /> 报备时间设置
                 </h2>
                 <div className="bg-blue-50 border border-blue-100 rounded-lg p-4 mb-6 text-sm text-blue-800">
                   <p>设置报备系统的开放时间窗口。如果在该时间段之外，移动端将无法提交数据。</p>
                   <p className="mt-1 font-medium">留空则表示不限制时间。</p>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div>
                     <label className="block text-sm font-medium text-gray-700 mb-2">开始时间</label>
                     <input 
                       type="datetime-local" 
                       className="w-full px-4 py-3 rounded-lg bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 text-gray-900"
                       value={settings?.reportingStartTime || ''}
                       onChange={(e) => setSettings({...settings, reportingStartTime: e.target.value})}
                     />
                   </div>
                   <div>
                     <label className="block text-sm font-medium text-gray-700 mb-2">截止时间</label>
                     <input 
                       type="datetime-local" 
                       className="w-full px-4 py-3 rounded-lg bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 text-gray-900"
                       value={settings?.reportingEndTime || ''}
                       onChange={(e) => setSettings({...settings, reportingEndTime: e.target.value})}
                     />
                   </div>
                 </div>
               </div>

               <hr className="border-gray-100" />

               {/* Logo Settings */}
               <div>
                 <h2 className="text-xl font-bold text-gray-900 mb-6 flex items-center gap-2">
                   <ImageIcon className="text-school-600" /> 首页 Logo 设置
                 </h2>

                 <div className="mb-6">
                   <label className="block text-sm font-medium text-gray-700 mb-2">当前预览</label>
                   <div className="bg-gray-50 border border-gray-200 rounded-lg p-4 flex items-center justify-center w-full sm:w-64 h-32">
                     <img 
                        src={settings.logoUrl || DEFAULT_LOGO} 
                        alt="Current Logo" 
                        className="max-h-full max-w-full object-contain"
                      />
                   </div>
                 </div>

                 <div className="space-y-4">
                   <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">上传图片</label>
                      <div className="flex gap-3">
                        <button 
                          onClick={triggerFileUpload}
                          className="flex items-center gap-2 bg-white border border-gray-300 text-gray-700 hover:bg-gray-50 px-4 py-2.5 rounded-lg text-sm font-medium transition shadow-sm"
                        >
                          <Upload size={16} /> 点击上传图片
                        </button>
                        <input 
                          type="file" 
                          ref={fileInputRef} 
                          className="hidden" 
                          accept="image/*" 
                          onChange={handleFileChange} 
                        />
                      </div>
                      <p className="text-xs text-gray-500 mt-2">支持 JPG, PNG 格式，建议大小不超过 1MB。</p>
                   </div>

                   <div className="relative">
                      <div className="absolute inset-0 flex items-center" aria-hidden="true">
                        <div className="w-full border-t border-gray-200"></div>
                      </div>
                      <div className="relative flex justify-center">
                        <span className="bg-white px-2 text-sm text-gray-500">或者</span>
                      </div>
                    </div>

                   <div>
                     <label className="block text-sm font-medium text-gray-700 mb-2">输入图片网址 (URL)</label>
                     <input 
                       type="text" 
                       className="w-full px-4 py-3 rounded-lg bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 text-gray-900 placeholder-gray-400"
                       value={settings?.logoUrl || ''}
                       onChange={(e) => setSettings({...settings, logoUrl: e.target.value})}
                       placeholder="例如: https://example.com/logo.png"
                     />
                     <p className="text-xs text-gray-500 mt-2">
                       如果直接上传了图片，此处的 URL 将会自动变为 Base64 编码。
                     </p>
                   </div>
                 </div>
               </div>

               <button 
                 onClick={handleSaveSettings}
                 className="flex items-center gap-2 bg-school-600 text-white px-6 py-3 rounded-xl font-medium hover:bg-school-700 transition"
               >
                 {settingsSaved ? <Check size={20} /> : null}
                 {settingsSaved ? '已保存设置' : '保存设置'}
               </button>
             </div>
          </div>
        )}
      </main>

      {/* --- MODALS --- */}

      {/* Password Modal */}
      {showPwdModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm p-6 relative">
            <button onClick={() => setShowPwdModal(false)} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"><X size={20} /></button>
            <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center gap-2"><Lock size={18} className="text-school-600" /> 修改管理员密码</h3>
            <form onSubmit={handlePasswordChange} className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">当前密码</label>
                <input type="password" value={oldPwd} onChange={(e) => setOldPwd(e.target.value)} className="w-full px-3 py-2 bg-gray-100 border-0 rounded-lg text-gray-900" />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">新密码</label>
                <input type="password" value={newPwd} onChange={(e) => setNewPwd(e.target.value)} className="w-full px-3 py-2 bg-gray-100 border-0 rounded-lg text-gray-900" />
              </div>
              {pwdError && <p className="text-red-500 text-xs">{pwdError}</p>}
              {pwdSuccess && <p className="text-green-500 text-xs">{pwdSuccess}</p>}
              <button type="submit" className="w-full bg-school-600 text-white py-2.5 rounded-lg font-medium hover:bg-school-700 transition">确认修改</button>
            </form>
          </div>
        </div>
      )}

      {/* Add User Modal */}
      {showUserModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm p-6 relative">
            <button onClick={() => setShowUserModal(false)} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"><X size={20} /></button>
