import React, { useEffect, useState, useRef } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer 
} from 'recharts';
import { Download, Sparkles, RefreshCw, LogOut, Users, Search, Lock, X, Clock, Plus, Trash2, Check, Image as ImageIcon, Upload } from 'lucide-react';
import { 
  getStudents, exportToCSV, verifyAdminPassword, changeAdminPassword, 
  getAppUsers, saveAppUser, deleteAppUser,
  getSystemSettings, saveSystemSettings 
} from '../services/dataService';
import { analyzeRecruitmentData } from '../services/geminiService';
import { Student, AnalysisResult, AppUser, SystemSettings } from '../types';

interface Props {
  onLogout: () => void;
}

type Tab = 'DASHBOARD' | 'USERS' | 'SETTINGS';

const DEFAULT_LOGO = "https://aistudiocdn.com/uploads/image-1065e8a7-331e-4530-9781-c7d58a5f57cc.png";

const AdminDashboard: React.FC<Props> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<Tab>('DASHBOARD');
  const [students, setStudents] = useState<Student[]>([]);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Password Modal
  const [showPwdModal, setShowPwdModal] = useState(false);
  const [oldPwd, setOldPwd] = useState('');
  const [newPwd, setNewPwd] = useState('');
  const [pwdError, setPwdError] = useState('');
  const [pwdSuccess, setPwdSuccess] = useState('');

  // User Management State
  const [appUsers, setAppUsers] = useState<AppUser[]>([]);
  const [showUserModal, setShowUserModal] = useState(false);
  const [userFormName, setUserFormName] = useState('');
  const [userFormIdCard, setUserFormIdCard] = useState('');
  const [userFormError, setUserFormError] = useState('');

  // Settings State
  const [settings, setSettings] = useState<SystemSettings>({ reportingStartTime: null, reportingEndTime: null, logoUrl: '' });
  const [settingsSaved, setSettingsSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    loadData();
    loadUsers();
    loadSettings();
  }, []);

  const loadData = () => {
    const data = getStudents();
    setStudents(Array.isArray(data) ? data : []);
  };

  const loadUsers = () => {
    const users = getAppUsers();
    setAppUsers(Array.isArray(users) ? users : []);
  };

  const loadSettings = () => {
    const s = getSystemSettings();
    // Ensure settings object is never null
    setSettings(s || { reportingStartTime: null, reportingEndTime: null, logoUrl: '' });
  };

  // --- Handlers ---

  const handleAnalysis = async () => {
    setAnalyzing(true);
    const result = await analyzeRecruitmentData(students);
    setAnalysis(result);
    setAnalyzing(false);
  };

  const handlePasswordChange = (e: React.FormEvent) => {
    e.preventDefault();
    setPwdError('');
    setPwdSuccess('');

    if (!verifyAdminPassword(oldPwd)) {
      setPwdError('原密码错误');
      return;
    }
    if (newPwd.length < 6) {
      setPwdError('新密码长度不能少于6位');
      return;
    }

    changeAdminPassword(newPwd);
    setPwdSuccess('密码修改成功');
    setTimeout(() => {
      setShowPwdModal(false);
      setOldPwd('');
      setNewPwd('');
      setPwdSuccess('');
    }, 1500);
  };

  const handleAddUser = (e: React.FormEvent) => {
    e.preventDefault();
    setUserFormError('');

    if (!userFormName || !userFormIdCard) {
      setUserFormError('请填写完整信息');
      return;
    }

    try {
      saveAppUser({
        username: userFormName,
        idCard: userFormIdCard,
        status: 'active'
      });
      setShowUserModal(false);
      setUserFormName('');
      setUserFormIdCard('');
      loadUsers();
    } catch (err: any) {
      setUserFormError(err.message || '添加失败');
    }
  };

  const handleDeleteUser = (id: string) => {
    if (confirm('确定要删除该管理员账号吗？删除后该用户将无法登录后台。')) {
      deleteAppUser(id);
      loadUsers();
    }
  };

  const handleSaveSettings = () => {
    saveSystemSettings(settings);
    setSettingsSaved(true);
    setTimeout(() => setSettingsSaved(false), 2000);
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Limit file size to 1MB to avoid filling up LocalStorage
    if (file.size > 1024 * 1024) {
      alert("为了保证系统性能，图片大小不能超过 1MB。");
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      setSettings(prev => ({ ...prev, logoUrl: base64String }));
    };
    reader.readAsDataURL(file);
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
  };

  // --- Chart Data ---
  const chartData = React.useMemo(() => {
    if (!Array.isArray(students)) return [];
    const last7Days = [...Array(7)].map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      return {
        date: date.slice(5),
        count: students.filter(s => s.reportTime && s.reportTime.startsWith(date)).length
      };
    });
  }, [students]);

  const filteredStudents = Array.isArray(students) ? students.filter(s => 
    (s.name || '').includes(searchTerm) || 
    (s.phoneNumber || '').includes(searchTerm)
  ) : [];

