                >
                  家长
                </button>
              </div>
              <input
                type="tel"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                placeholder={contactType === 'student' ? "请输入学生电话" : "请输入家长电话"}
                className="w-full px-4 py-3.5 rounded-xl bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 focus:bg-white outline-none transition text-gray-900 placeholder-gray-400"
              />
            </div>

            {error && (
              <div className="p-3 bg-red-50 text-red-600 text-sm rounded-xl border border-red-100 flex items-start gap-2">
                 <AlertTriangle size={16} className="mt-0.5 shrink-0" /> 
                 <span>{error}</span>
              </div>
            )}

            <button
              type="submit"
              className="w-full bg-school-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg shadow-blue-200 hover:bg-school-700 transition duration-200 flex items-center justify-center gap-2 mt-4"
            >
              <Send size={20} /> 立即报备
            </button>
          </form>
        </div>

        <p className="text-center text-[#05A7E2] text-xs mt-6">
          成都城市建设技工学校 • 报备系统
        </p>
      </div>
    </div>
  );
};

export default StudentForm;

import React, { useState, useEffect } from 'react';
import StudentForm from './components/StudentForm';
import AdminDashboard from './components/AdminDashboard';
import { Recruiter, SystemSettings } from './types';
import { loginAdmin, validateReporter, getSystemSettings, isReportingTimeValid } from './services/dataService';
import { School, User, ChevronRight, Smartphone, Monitor, Lock } from 'lucide-react';

type SystemMode = 'PORTAL' | 'STUDENT_APP' | 'ADMIN_APP';

const DEFAULT_LOGO = "https://pic1.imgdb.cn/item/69383a2df9354404e341391f.jpg";

const App: React.FC = () => {
  const [mode, setMode] = useState<SystemMode>('PORTAL');
  const [currentUser, setCurrentUser] = useState<Recruiter | null>(null);
  // Initialize with current settings directly to avoid flash of default logo
  const [settings, setSettings] = useState<SystemSettings>(getSystemSettings());

  // Authentication State for sub-apps
  const [username, setUsername] = useState('');
  const [loginPhone, setLoginPhone] = useState('');
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState('');

  // Effect to handle URL based "Routing" and Browser Back/Forward buttons
  useEffect(() => {
    const handleUrlChange = () => {
      const params = new URLSearchParams(window.location.search);
      const appParam = params.get('app');
      if (appParam === 'student') {
        setMode('STUDENT_APP');
      } else if (appParam === 'admin') {
        setMode('ADMIN_APP');
      } else {
        setMode('PORTAL');
      }
    };

    handleUrlChange();
    window.addEventListener('popstate', handleUrlChange);

    // Refresh settings in case they changed in another tab/window
    setSettings(getSystemSettings());

    return () => window.removeEventListener('popstate', handleUrlChange);
  }, []);

  const changeMode = (newMode: SystemMode) => {
    setMode(newMode);
    const url = new URL(window.location.href);

    if (newMode === 'STUDENT_APP') {
      url.searchParams.set('app', 'student');
      window.history.pushState({}, '', url);
    } else if (newMode === 'ADMIN_APP') {
      url.searchParams.set('app', 'admin');
      window.history.pushState({}, '', url);
    } else {
      url.searchParams.delete('app');
      window.history.pushState({}, '', url);
    }
  };

  const handleLogin = (e: React.FormEvent, targetRole: 'user' | 'admin') => {
    e.preventDefault();
    setLoginError('');

    if (!username.trim()) {
      setLoginError('请输入账号/姓名');
      return;
    }

    // --- Admin Login ---
    if (targetRole === 'admin') {
      if (!password) {
        setLoginError('请输入密码 (或子管理员身份证号)');
        return;
      }

      const adminUser = loginAdmin(username.trim(), password.trim());
      if (adminUser) {
        setCurrentUser(adminUser);
      } else {
        setLoginError('登录失败：账号或密码错误');
      }
      return;
    } 

    // --- Student/User Login (Information Reporting) ---
    // No database check needed, just validation
    if (targetRole === 'user') {
      // Check if reporting time window is valid
      const timeCheck = isReportingTimeValid();
      if (!timeCheck.valid) {
        setLoginError(timeCheck.message || '当前不在报备时间内');
        return;
      }

      if (!loginPhone.trim()) {
        setLoginError('请输入手机号码');
        return;
      }

      const user = validateReporter(username.trim(), loginPhone.trim());

      if (user) {
        setCurrentUser(user);
      } else {
        setLoginError('登录失败：请输入有效的11位手机号码');
      }
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setUsername('');
    setLoginPhone('');
    setPassword('');
    setLoginError('');
  };

  // --- PORTAL VIEW ---
  if (mode === 'PORTAL') {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-4xl">
          <div className="text-center mb-16">
            <img 
              src={settings.logoUrl || DEFAULT_LOGO} 
              alt="Chengdu School Logo" 
              className="w-32 h-32 mx-auto mb-8 object-contain drop-shadow-lg"
            />
            <h1 className="text-4xl md:text-6xl font-extrabold text-[#05A7E2] tracking-tight leading-tight">
              成都城市建设技工学校
            </h1>
            <p className="text-gray-500 mt-4 text-xl">综合信息管理平台</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <button 
              onClick={() => changeMode('STUDENT_APP')}
              className="group relative bg-white rounded-3xl p-8 shadow-xl hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1 text-left overflow-hidden border border-gray-100 ring-1 ring-gray-100"
            >
              <div className="absolute top-0 right-0 bg-blue-50 w-32 h-32 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110"></div>
              <div className="relative z-10">
                <div className="bg-blue-100 w-14 h-14 rounded-2xl flex items-center justify-center mb-6 text-blue-600 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                  <Smartphone size={28} />
                </div>
                <h2 className="text-2xl font-bold text-gray-800 mb-2">信息报备</h2>
                <p className="text-gray-500 mb-6">H5 移动端 • 新生信息录入</p>
                <div className="flex items-center text-blue-600 font-semibold group-hover:translate-x-2 transition-transform">
                  进入系统 <ChevronRight className="ml-1" size={20} />
                </div>
              </div>
            </button>

            <button 
              onClick={() => changeMode('ADMIN_APP')}
              className="group relative bg-gray-50 rounded-3xl p-8 shadow-xl hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1 text-left overflow-hidden border border-gray-200"
            >
              <div className="absolute top-0 right-0 bg-gray-200 w-32 h-32 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110 opacity-50"></div>
              <div className="relative z-10">
                <div className="bg-white w-14 h-14 rounded-2xl flex items-center justify-center mb-6 text-gray-700 group-hover:bg-gray-800 group-hover:text-white transition-colors shadow-sm">
                  <Monitor size={28} />
                </div>
                <h2 className="text-2xl font-bold text-gray-900 mb-2">管理后台</h2>
                <p className="text-gray-500 mb-6">Web 端 • 数据管理与分析</p>
                <div className="flex items-center text-gray-700 font-semibold group-hover:translate-x-2 transition-transform">
                  进入后台 <ChevronRight className="ml-1" size={20} />
                </div>
              </div>
            </button>
          </div>

          <p className="text-center text-gray-400 text-sm mt-12">
             请选择对应的入口进入系统
          </p>
        </div>
      </div>
    );
  }

  // --- STUDENT APP FLOW (Information Reporting) ---
  if (mode === 'STUDENT_APP') {
    if (!currentUser) {
      return (
        <div className="min-h-screen bg-white flex flex-col">
          <div className="flex-1 flex flex-col justify-center px-6">
            <div className="w-full max-w-sm mx-auto">
              <div className="text-center mb-10">
                 {/* Logo Area */}
                <div className="w-24 h-24 mx-auto mb-4 flex items-center justify-center">
                   <img 
                      src={settings.logoUrl || DEFAULT_LOGO} 
                      alt="Logo" 
                      className="w-full h-full object-contain"
                    />
                </div>

                <h2 className="text-3xl font-bold text-[#05A7E2] mb-2">成都城市建设技工学校</h2>
                <h1 className="text-xl font-bold text-gray-900">信息报备</h1>
                <p className="text-gray-500 text-sm mt-2">请输入姓名和手机号开始录入</p>
              </div>
              <form onSubmit={(e) => handleLogin(e, 'user')} className="space-y-6">

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">姓名</label>
                  <div className="relative">
                    <input
                      type="text"
                      value={username}
                      onChange={(e) => setUsername(e.target.value)}
                      className="w-full pl-10 pr-4 py-4 rounded-xl bg-gray-50 border border-gray-200 focus:ring-2 focus:ring-school-500 focus:bg-white transition text-gray-900 placeholder-gray-400"
                      autoComplete="off"
                      placeholder="请输入您的姓名"
                    />
                    <User className="absolute left-3 top-4 text-gray-400" size={20} />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">手机号码</label>
                  <div className="relative">
                    <input
                      type="tel"
                      value={loginPhone}
                      onChange={(e) => setLoginPhone(e.target.value)}
                      className="w-full pl-10 pr-4 py-4 rounded-xl bg-gray-50 border border-gray-200 focus:ring-2 focus:ring-school-500 focus:bg-white transition text-gray-900 placeholder-gray-400"
                      maxLength={11}
                      autoComplete="off"
                      placeholder="请输入11位手机号码"
                    />
                    <Smartphone className="absolute left-3 top-4 text-gray-400" size={20} />
                  </div>
                </div>

                {loginError && <p className="text-red-500 text-sm text-center">{loginError}</p>}

                <button type="submit" className="w-full bg-school-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg hover:bg-school-700 transition">
                  进入系统
                </button>
              </form>
            </div>
          </div>
        </div>
      );
    }
    return <StudentForm user={currentUser} onLogout={handleLogout} />;
  }

  // --- ADMIN APP FLOW ---
  if (mode === 'ADMIN_APP') {
    if (!currentUser) {
      return (
        <div className="min-h-screen bg-white flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl border border-gray-100 w-full max-w-md overflow-hidden flex flex-col md:flex-row">
            <div className="w-full p-8 md:p-10">
              <div className="text-center mb-8">
                <img 
                  src={settings.logoUrl || DEFAULT_LOGO} 
                  alt="Logo" 
                  className="w-20 h-20 mx-auto mb-4 object-contain"
                />
                <h2 className="text-2xl font-bold text-[#05A7E2] mb-2">成都城市建设技工学校</h2>
                <h3 className="text-xl font-bold text-gray-900">管理后台登录</h3>
                <p className="text-gray-500 text-sm mt-2">仅限管理人员访问</p>
              </div>
              <form onSubmit={(e) => handleLogin(e, 'admin')} className="space-y-5">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">管理员账号</label>
                  <input
                    type="text"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    className="w-full px-4 py-3 rounded-lg bg-gray-50 border border-gray-200 focus:ring-2 focus:ring-blue-500 focus:bg-white transition text-gray-900 placeholder-gray-400"
                    autoComplete="off"
                    placeholder="请输入管理员账号"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">管理员密码</label>
                  <div className="relative">
                    <input
                      type="password"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className="w-full px-4 py-3 rounded-lg bg-gray-50 border border-gray-200 focus:ring-2 focus:ring-blue-500 focus:bg-white transition text-gray-900 placeholder-gray-400"
                      autoComplete="new-password"
                      placeholder="请输入密码"
                    />
                    <Lock className="absolute right-3 top-3.5 text-gray-400" size={18} />
                  </div>
                </div>
                {loginError && <div className="p-3 bg-red-50 text-red-600 text-xs rounded-lg">{loginError}</div>}
                <button type="submit" className="w-full bg-slate-900 text-white py-3 rounded-lg font-semibold hover:bg-slate-800 transition">
                  安全登录
                </button>
              </form>
            </div>
          </div>
        </div>
      );
    }
    return <AdminDashboard onLogout={handleLogout} />;
  }

  return null;
};

export default App;

import { Student, Recruiter, AppUser, SystemSettings } from '../types';

const STUDENTS_KEY = 'chengdu_school_students';
const APP_USERS_KEY = 'chengdu_school_app_users';
const SETTINGS_KEY = 'chengdu_school_settings';
const CURRENT_USER_KEY = 'chengdu_school_current_user';
const ADMIN_PASSWORD_KEY = 'chengdu_school_admin_password';
const DEFAULT_PASSWORD = 'system123@';

// Mock initial admin
const MOCK_ADMIN: Recruiter = { id: 'admin-1', username: 'admin', role: 'admin' };

const generateId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

// --- Student Data ---

export const getStudents = (): Student[] => {
  try {
    const data = localStorage.getItem(STUDENTS_KEY);
    if (!data) return [];
    const parsed = JSON.parse(data);
    return Array.isArray(parsed) ? parsed.filter(item => item && typeof item === 'object') : [];
  } catch (error) {
    console.error("Error reading students", error);
    return [];
  }
};

export const saveStudent = (student: Omit<Student, 'id' | 'reportTime'>): Student => {
  const students = getStudents();
  const newStudent: Student = {
    ...student,
    id: generateId(),
    reportTime: new Date().toISOString(),
  };

  const updatedStudents = [newStudent, ...students];
  localStorage.setItem(STUDENTS_KEY, JSON.stringify(updatedStudents));
  return newStudent;
};

// --- User Management (Now for Additional Admins) ---

export const getAppUsers = (): AppUser[] => {
  try {
    const data = localStorage.getItem(APP_USERS_KEY);
    if (!data) return [];
    const parsed = JSON.parse(data);
    return Array.isArray(parsed) ? parsed.filter(item => item && typeof item === 'object') : [];
  } catch (error) {
    return [];
  }
};

export const saveAppUser = (user: Omit<AppUser, 'id' | 'createdAt' | 'role'>): AppUser => {
  const users = getAppUsers();

  // Check for duplicates
  if (users.some(u => u.idCard === user.idCard)) {
    throw new Error("该身份证号已存在");
  }

  const newUser: AppUser = {
    ...user,
    id: generateId(),
    role: 'user', // In types.ts role is 'user', but logically these act as sub-admins now. We keep type as 'user' to avoid breaking interface but treat them as admins in login.
    createdAt: new Date().toISOString(),
  };

  const updatedUsers = [newUser, ...users];
  localStorage.setItem(APP_USERS_KEY, JSON.stringify(updatedUsers));
  return newUser;
};

export const updateAppUser = (id: string, updates: Partial<AppUser>): void => {
  const users = getAppUsers();
  const updatedUsers = users.map(u => u.id === id ? { ...u, ...updates } : u);
  localStorage.setItem(APP_USERS_KEY, JSON.stringify(updatedUsers));
};

export const deleteAppUser = (id: string): void => {
  const users = getAppUsers();
  const updatedUsers = users.filter(u => u.id !== id);
  localStorage.setItem(APP_USERS_KEY, JSON.stringify(updatedUsers));
};

// --- Authentication ---

// 1. Admin Login: Checks Super Admin OR App Users (Sub-admins)
export const loginAdmin = (username: string, passwordOrIdCard: string): Recruiter | null => {
  // A. Super Admin Check
  if (username === 'admin') {
    if (verifyAdminPassword(passwordOrIdCard)) {
      return MOCK_ADMIN;
    }
    return null;
  }

  // B. Sub-Admin Check (from User Management list)
  // For sub-admins, we treat the username as Name and ID Card as the password
  const users = getAppUsers();
  const foundUser = users.find(u => 
    u.username === username && 
    u.idCard === passwordOrIdCard && 
    u.status === 'active'
  );

  if (foundUser) {
    return {
      id: foundUser.id,
      username: foundUser.username,
      role: 'admin' // Grant admin access
    };
  }

  return null;
};

// 2. Student/Reporter Login: Open access, just validation
export const validateReporter = (username: string, phoneNumber: string): Recruiter | null => {
  if (!username) return null;

  // Valid Mobile Phone Number (China)
  const phoneRegex = /^1[3-9]\d{9}$/;

  if (!phoneRegex.test(phoneNumber)) {
    return null;
  }

  return {
    id: phoneNumber, // Use Phone as temporary session ID
    username: username,
    role: 'user'
  };
};

export const verifyAdminPassword = (inputPassword: string): boolean => {
  try {
    const stored = localStorage.getItem(ADMIN_PASSWORD_KEY);
    const currentPassword = stored || DEFAULT_PASSWORD;
    if (!stored) {
      localStorage.setItem(ADMIN_PASSWORD_KEY, DEFAULT_PASSWORD);
    }
    return inputPassword === currentPassword;
  } catch {
    return false;
  }
};

export const changeAdminPassword = (newPassword: string): void => {
  try {
    localStorage.setItem(ADMIN_PASSWORD_KEY, newPassword);
  } catch (e) {
    console.error(e);
  }
};

// --- System Settings (Time Window) ---

export const getSystemSettings = (): SystemSettings => {
  try {
    const data = localStorage.getItem(SETTINGS_KEY);
    if (!data) return { reportingStartTime: null, reportingEndTime: null, logoUrl: '' };
    const parsed = JSON.parse(data);
    return parsed || { reportingStartTime: null, reportingEndTime: null, logoUrl: '' };
  } catch {
    return { reportingStartTime: null, reportingEndTime: null, logoUrl: '' };
  }
};

export const saveSystemSettings = (settings: SystemSettings): void => {
  localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
};

export const isReportingTimeValid = (): { valid: boolean; message?: string } => {
  const settings = getSystemSettings();
  const now = new Date().getTime();

  // Handle Start Time
  const startStr = settings.reportingStartTime;
  if (startStr && startStr.trim() !== '') {
    const startDate = new Date(startStr);
    // Check if date is valid
    if (!isNaN(startDate.getTime())) {
       if (now < startDate.getTime()) {
         return { valid: false, message: `系统未开放。开放时间: ${startDate.toLocaleString()}` };
       }
    }
  }

  // Handle End Time
  const endStr = settings.reportingEndTime;
  if (endStr && endStr.trim() !== '') {
    const endDate = new Date(endStr);
    // Check if date is valid
    if (!isNaN(endDate.getTime())) {
       if (now > endDate.getTime()) {
         return { valid: false, message: `报备已截止。截止时间: ${endDate.toLocaleString()}` };
       }
    }
  }

  return { valid: true };
};

// --- Misc ---

export const exportToCSV = (): void => {
  const students = getStudents();
  if (students.length === 0) {
    alert("暂无数据可导出");
    return;
  }

  const headers = ["ID", "姓名", "电话", "电话归属", "报备时间", "填报人ID"];
  const csvContent = [
    headers.join(","),
    ...students.map(s => [
      s.id,
      s.name,
      s.phoneNumber,
      s.contactType === 'student' ? '学生本人' : '家长',
      new Date(s.reportTime).toLocaleString(),
      s.recruiterId
    ].join(","))
  ].join("\n");

  const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.setAttribute("href", url);
  link.setAttribute("download", `报备数据_${new Date().toISOString().slice(0,10)}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

export const getCurrentUser = (): Recruiter | null => {
  try {
    const data = localStorage.getItem(CURRENT_USER_KEY);
    return data ? JSON.parse(data) : null;
  } catch {
    return null;
  }
};

export const setCurrentUser = (user: Recruiter | null) => {
  try {
    if (user) {
      localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user));
    } else {
      localStorage.removeItem(CURRENT_USER_KEY);
    }
  } catch (e) {
    console.error("Storage error", e);
  }
};

import React, { useState, useEffect } from 'react';
import StudentForm from './components/StudentForm';
import AdminDashboard from './components/AdminDashboard';
import { Recruiter, SystemSettings } from './types';
import { loginAdmin, validateReporter, getSystemSettings, isReportingTimeValid } from './services/dataService';
import { School, User, ChevronRight, Smartphone, Monitor, Lock, Clock, AlertCircle } from 'lucide-react';

type SystemMode = 'PORTAL' | 'STUDENT_APP' | 'ADMIN_APP';

const DEFAULT_LOGO = "https://pic1.imgdb.cn/item/69383a2df9354404e341391f.jpg";

const App: React.FC = () => {
  const [mode, setMode] = useState<SystemMode>('PORTAL');
  const [currentUser, setCurrentUser] = useState<Recruiter | null>(null);
  // Initialize with current settings directly to avoid flash of default logo
  const [settings, setSettings] = useState<SystemSettings>(getSystemSettings());

  // Authentication State for sub-apps
  const [username, setUsername] = useState('');
  const [loginPhone, setLoginPhone] = useState('');
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState('');

  // Effect to handle URL based "Routing" and Browser Back/Forward buttons
  useEffect(() => {
    const handleUrlChange = () => {
      const params = new URLSearchParams(window.location.search);
      const appParam = params.get('app');
      if (appParam === 'student') {
        setMode('STUDENT_APP');
      } else if (appParam === 'admin') {
        setMode('ADMIN_APP');
      } else {
        setMode('PORTAL');
      }
    };

    handleUrlChange();
    window.addEventListener('popstate', handleUrlChange);

    // Sync settings across tabs
    const handleStorageChange = () => {
      setSettings(getSystemSettings());
    };
    window.addEventListener('storage', handleStorageChange);

    return () => {
      window.removeEventListener('popstate', handleUrlChange);
      window.removeEventListener('storage', handleStorageChange);
    };
  }, []);

  const changeMode = (newMode: SystemMode) => {
    setMode(newMode);
    const url = new URL(window.location.href);

    if (newMode === 'STUDENT_APP') {
      url.searchParams.set('app', 'student');
      window.history.pushState({}, '', url);
    } else if (newMode === 'ADMIN_APP') {
      url.searchParams.set('app', 'admin');
      window.history.pushState({}, '', url);
    } else {
      url.searchParams.delete('app');
      window.history.pushState({}, '', url);
    }
  };

  const handleLogin = (e: React.FormEvent, targetRole: 'user' | 'admin') => {
    e.preventDefault();
    setLoginError('');

    if (!username.trim()) {
      setLoginError('请输入账号/姓名');
      return;
    }

    // --- Admin Login ---
    if (targetRole === 'admin') {
      if (!password) {
        setLoginError('请输入密码 (或子管理员身份证号)');
        return;
      }

      const adminUser = loginAdmin(username.trim(), password.trim());
      if (adminUser) {
        setCurrentUser(adminUser);
      } else {
        setLoginError('登录失败：账号或密码错误');
      }
      return;
    } 

    // --- Student/User Login (Information Reporting) ---
    // No database check needed, just validation
    if (targetRole === 'user') {
      // Check if reporting time window is valid (Backup check)
      const timeCheck = isReportingTimeValid();
      if (!timeCheck.valid) {
        setLoginError(timeCheck.message || '当前不在报备时间内');
        return;
      }

      if (!loginPhone.trim()) {
        setLoginError('请输入手机号码');
        return;
      }

      const user = validateReporter(username.trim(), loginPhone.trim());

      if (user) {
        setCurrentUser(user);
      } else {
        setLoginError('登录失败：请输入有效的11位手机号码');
      }
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setUsername('');
    setLoginPhone('');
    setPassword('');
    setLoginError('');
  };

  // --- PORTAL VIEW ---
  if (mode === 'PORTAL') {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-4xl">
          <div className="text-center mb-16">
            <img 
              src={settings.logoUrl || DEFAULT_LOGO} 
              alt="Chengdu School Logo" 
              className="w-32 h-32 mx-auto mb-8 object-contain drop-shadow-lg"
            />
            <h1 className="text-4xl md:text-6xl font-extrabold text-[#05A7E2] tracking-tight leading-tight">
              成都城市建设技工学校
            </h1>
            <p className="text-gray-500 mt-4 text-xl">综合信息管理平台</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <button 
              onClick={() => changeMode('STUDENT_APP')}
              className="group relative bg-white rounded-3xl p-8 shadow-xl hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1 text-left overflow-hidden border border-gray-100 ring-1 ring-gray-100"
            >
              <div className="absolute top-0 right-0 bg-blue-50 w-32 h-32 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110"></div>
              <div className="relative z-10">
                <div className="bg-blue-100 w-14 h-14 rounded-2xl flex items-center justify-center mb-6 text-blue-600 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                  <Smartphone size={28} />
                </div>
                <h2 className="text-2xl font-bold text-gray-800 mb-2">信息报备</h2>
                <p className="text-gray-500 mb-6">H5 移动端 • 新生信息录入</p>
                <div className="flex items-center text-blue-600 font-semibold group-hover:translate-x-2 transition-transform">
                  进入系统 <ChevronRight className="ml-1" size={20} />
                </div>
              </div>
            </button>

            <button 
              onClick={() => changeMode('ADMIN_APP')}
              className="group relative bg-gray-50 rounded-3xl p-8 shadow-xl hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1 text-left overflow-hidden border border-gray-200"
            >
              <div className="absolute top-0 right-0 bg-gray-200 w-32 h-32 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110 opacity-50"></div>
              <div className="relative z-10">
                <div className="bg-white w-14 h-14 rounded-2xl flex items-center justify-center mb-6 text-gray-700 group-hover:bg-gray-800 group-hover:text-white transition-colors shadow-sm">
                  <Monitor size={28} />
                </div>
                <h2 className="text-2xl font-bold text-gray-900 mb-2">管理后台</h2>
                <p className="text-gray-500 mb-6">Web 端 • 数据管理与分析</p>
                <div className="flex items-center text-gray-700 font-semibold group-hover:translate-x-2 transition-transform">
                  进入后台 <ChevronRight className="ml-1" size={20} />
                </div>
              </div>
            </button>
          </div>

          <p className="text-center text-gray-400 text-sm mt-12">
             请选择对应的入口进入系统
          </p>
        </div>
      </div>
    );
  }

  // --- STUDENT APP FLOW (Information Reporting) ---
  if (mode === 'STUDENT_APP') {
    // Immediate check: If time is invalid, BLOCK the view completely before showing login
    // We also check !currentUser because if they are already in a session, we might want to let them finish (optional), 
    // but based on "cannot enter system", blocking new entries is priority.
    // StudentForm also performs this check on submit.
    const timeCheck = isReportingTimeValid();

    if (!currentUser && !timeCheck.valid) {
        return (
            <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
                <div className="bg-white p-10 rounded-3xl shadow-xl w-full max-w-sm text-center border border-gray-100">
                    <div className="w-20 h-20 bg-red-50 rounded-full flex items-center justify-center mx-auto mb-6 text-red-500 ring-8 ring-red-50/50">
                        <Clock size={40} />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-900 mb-3">系统暂未开放</h2>
                    <p className="text-gray-500 mb-8 text-sm leading-relaxed border-t border-b border-gray-100 py-4">
                        {timeCheck.message}
                    </p>
                    <button 
                        onClick={() => changeMode('PORTAL')}
                        className="w-full bg-gray-900 text-white py-3.5 rounded-xl font-bold hover:bg-gray-800 transition shadow-lg shadow-gray-200"
                    >
                        返回首页
                    </button>
                </div>
                <div className="mt-8 opacity-40 grayscale flex flex-col items-center gap-2">
                    <img src={settings.logoUrl || DEFAULT_LOGO} className="h-8 object-contain" />
                    <span className="text-xs text-gray-400">成都城市建设技工学校</span>
                </div>
            </div>
        );
    }

    if (!currentUser) {
      return (
        <div className="min-h-screen bg-white flex flex-col">
          <div className="flex-1 flex flex-col justify-center px-6">
            <div className="w-full max-w-sm mx-auto">
              <div className="text-center mb-10">
                 {/* Logo Area */}
                <div className="w-24 h-24 mx-auto mb-4 flex items-center justify-center">
                   <img 
                      src={settings.logoUrl || DEFAULT_LOGO} 
                      alt="Logo" 
                      className="w-full h-full object-contain"
                    />
                </div>

                <h2 className="text-3xl font-bold text-[#05A7E2] mb-2">成都城市建设技工学校</h2>
                <h1 className="text-xl font-bold text-gray-900">信息报备</h1>
                <p className="text-gray-500 text-sm mt-2">请输入姓名和手机号开始录入</p>
              </div>
              <form onSubmit={(e) => handleLogin(e, 'user')} className="space-y-6">

                <div>
