import { Student, Recruiter, AppUser, SystemSettings } from '../types';

const STUDENTS_KEY = 'chengdu_school_students';
const APP_USERS_KEY = 'chengdu_school_app_users';
const SETTINGS_KEY = 'chengdu_school_settings';
const CURRENT_USER_KEY = 'chengdu_school_current_user';
const ADMIN_PASSWORD_KEY = 'chengdu_school_admin_password';
const DEFAULT_PASSWORD = 'system123@';

// Mock initial admin
const MOCK_ADMIN: Recruiter = { id: 'admin-1', username: 'admin', role: 'admin' };

const generateId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

// --- Student Data ---

export const getStudents = (): Student[] => {
  try {
    const data = localStorage.getItem(STUDENTS_KEY);
    if (!data) return [];
    const parsed = JSON.parse(data);
    return Array.isArray(parsed) ? parsed.filter(item => item && typeof item === 'object') : [];
  } catch (error) {
    console.error("Error reading students", error);
    return [];
  }
};

export const saveStudent = (student: Omit<Student, 'id' | 'reportTime'>): Student => {
  const students = getStudents();
  const newStudent: Student = {
    ...student,
    id: generateId(),
    reportTime: new Date().toISOString(),
  };

  const updatedStudents = [newStudent, ...students];
  localStorage.setItem(STUDENTS_KEY, JSON.stringify(updatedStudents));
  return newStudent;
};

// --- User Management (Now for Additional Admins) ---

export const getAppUsers = (): AppUser[] => {
  try {
    const data = localStorage.getItem(APP_USERS_KEY);
    if (!data) return [];
    const parsed = JSON.parse(data);
    return Array.isArray(parsed) ? parsed.filter(item => item && typeof item === 'object') : [];
  } catch (error) {
    return [];
  }
};

export const saveAppUser = (user: Omit<AppUser, 'id' | 'createdAt' | 'role'>): AppUser => {
  const users = getAppUsers();

  // Check for duplicates
  if (users.some(u => u.idCard === user.idCard)) {
    throw new Error("该身份证号已存在");
  }

  const newUser: AppUser = {
    ...user,
    id: generateId(),
    role: 'user', // In types.ts role is 'user', but logically these act as sub-admins now. We keep type as 'user' to avoid breaking interface but treat them as admins in login.
    createdAt: new Date().toISOString(),
  };

  const updatedUsers = [newUser, ...users];
  localStorage.setItem(APP_USERS_KEY, JSON.stringify(updatedUsers));
  return newUser;
};

export const updateAppUser = (id: string, updates: Partial<AppUser>): void => {
  const users = getAppUsers();
  const updatedUsers = users.map(u => u.id === id ? { ...u, ...updates } : u);
  localStorage.setItem(APP_USERS_KEY, JSON.stringify(updatedUsers));
};

export const deleteAppUser = (id: string): void => {
  const users = getAppUsers();
  const updatedUsers = users.filter(u => u.id !== id);
  localStorage.setItem(APP_USERS_KEY, JSON.stringify(updatedUsers));
};

// --- Authentication ---

// 1. Admin Login: Checks Super Admin OR App Users (Sub-admins)
export const loginAdmin = (username: string, passwordOrIdCard: string): Recruiter | null => {
  // A. Super Admin Check
  if (username === 'admin') {
    if (verifyAdminPassword(passwordOrIdCard)) {
      return MOCK_ADMIN;
    }
    return null;
  }

  // B. Sub-Admin Check (from User Management list)
  // For sub-admins, we treat the username as Name and ID Card as the password
  const users = getAppUsers();
  const foundUser = users.find(u => 
    u.username === username && 
    u.idCard === passwordOrIdCard && 
    u.status === 'active'
  );

  if (foundUser) {
    return {
      id: foundUser.id,
      username: foundUser.username,
      role: 'admin' // Grant admin access
    };
  }

  return null;
};

// 2. Student/Reporter Login: Open access, just validation
export const validateReporter = (username: string, phoneNumber: string): Recruiter | null => {
  if (!username) return null;

  // Valid Mobile Phone Number (China)
  const phoneRegex = /^1[3-9]\d{9}$/;

  if (!phoneRegex.test(phoneNumber)) {
    return null;
  }

  return {
    id: phoneNumber, // Use Phone as temporary session ID (Recruiter ID)
    username: username,
    role: 'user'
  };
};

export const verifyAdminPassword = (inputPassword: string): boolean => {
  try {
    const stored = localStorage.getItem(ADMIN_PASSWORD_KEY);
    const currentPassword = stored || DEFAULT_PASSWORD;
    if (!stored) {
      localStorage.setItem(ADMIN_PASSWORD_KEY, DEFAULT_PASSWORD);
    }
    return inputPassword === currentPassword;
  } catch {
    return false;
  }
};

export const changeAdminPassword = (newPassword: string): void => {
  try {
    localStorage.setItem(ADMIN_PASSWORD_KEY, newPassword);
  } catch (e) {
    console.error(e);
  }
};

// --- System Settings (Time Window) ---

export const getSystemSettings = (): SystemSettings => {
  try {
    const data = localStorage.getItem(SETTINGS_KEY);
    if (!data) return { reportingStartTime: null, reportingEndTime: null, logoUrl: '' };
    const parsed = JSON.parse(data);
    return parsed || { reportingStartTime: null, reportingEndTime: null, logoUrl: '' };
  } catch {
    return { reportingStartTime: null, reportingEndTime: null, logoUrl: '' };
  }
};

export const saveSystemSettings = (settings: SystemSettings): void => {
  localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
};

export const isReportingTimeValid = (): { valid: boolean; message?: string } => {
  const settings = getSystemSettings();
  const now = new Date().getTime();

  // Handle Start Time
  const startStr = settings.reportingStartTime;
  // Handle End Time
  const endStr = settings.reportingEndTime;

  const hasStart = startStr && startStr.trim() !== '';
  const hasEnd = endStr && endStr.trim() !== '';

  // REQUIREMENT: If no time configured, default to invalid (Closed).
  if (!hasStart && !hasEnd) {
    return { valid: false, message: '系统未开启：后台暂未配置报备时间。' };
  }

  if (hasStart) {
    const startDate = new Date(startStr);
    // Check if date is valid
    if (!isNaN(startDate.getTime())) {
       if (now < startDate.getTime()) {
         return { valid: false, message: `系统未开放。开放时间: ${startDate.toLocaleString()}` };
       }
    }
  }

  // Handle End Time
  if (hasEnd) {
    const endDate = new Date(endStr);
    // Check if date is valid
    if (!isNaN(endDate.getTime())) {
       if (now > endDate.getTime()) {
         return { valid: false, message: `报备已截止。截止时间: ${endDate.toLocaleString()}` };
       }
    }
  }

  return { valid: true };
};

// --- Misc ---

export const exportToCSV = (data?: Student[]): void => {
  // Use provided data if available, otherwise fetch all
  const students = data || getStudents();

  if (students.length === 0) {
    alert("暂无数据可导出");
    return;
  }

  const headers = ["ID", "姓名", "电话", "电话归属", "报备时间", "填报人", "填报人电话"];
  const csvContent = [
    headers.join(","),
    ...students.map(s => [
      s.id,
      s.name,
      s.phoneNumber,
      s.contactType === 'student' ? '学生本人' : '家长',
      new Date(s.reportTime).toLocaleString(),
      s.recruiterName || s.recruiterId, // Fallback to ID if name missing
      s.recruiterPhone || s.recruiterId // Use stored phone or ID (which is phone for normal users)
    ].join(","))
  ].join("\n");

  const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.setAttribute("href", url);

  // Distinguish filename if it's a filtered export
  const prefix = data ? '筛选报备数据' : '全部报备数据';
  link.setAttribute("download", `${prefix}_${new Date().toISOString().slice(0,10)}.csv`);

  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

export const getCurrentUser = (): Recruiter | null => {
