export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import StudentForm from './components/StudentForm';
import AdminDashboard from './components/AdminDashboard';
import { Recruiter, SystemSettings } from './types';
import { loginAdmin, validateReporter, getSystemSettings, isReportingTimeValid } from './services/dataService';
import { School, User, ChevronRight, Smartphone, Monitor, Lock, Clock, AlertCircle } from 'lucide-react';

type SystemMode = 'PORTAL' | 'STUDENT_APP' | 'ADMIN_APP';

const DEFAULT_LOGO = "https://pic1.imgdb.cn/item/69383a2df9354404e341391f.jpg";

const App: React.FC = () => {
  const [mode, setMode] = useState<SystemMode>('PORTAL');
  const [currentUser, setCurrentUser] = useState<Recruiter | null>(null);
  const [settings, setSettings] = useState<SystemSettings>({ reportingStartTime: null, reportingEndTime: null, logoUrl: '' });
  const [loading, setLoading] = useState(true);
  const [initError, setInitError] = useState<string>('');

  // Authentication State for sub-apps
  const [username, setUsername] = useState('');
  const [loginPhone, setLoginPhone] = useState('');
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState('');

  // Initial Data Load
  useEffect(() => {
    const init = async () => {
      try {
        const s = await getSystemSettings();
        setSettings(s);
      } catch (e) {
        console.error("Initialization error:", e);
        // Do not block app completely, but log error. 
        // We might fail to get settings but defaults are set.
        // If DB is completely broken, we might want to show critical error.
        setInitError("系统初始化失败：无法连接本地数据库。请检查浏览器隐私设置或尝试刷新页面。");
      } finally {
        setLoading(false);
      }
    };
    init();

    const handleUrlChange = () => {
      const params = new URLSearchParams(window.location.search);
      const appParam = params.get('app');
      if (appParam === 'student') {
        setMode('STUDENT_APP');
      } else if (appParam === 'admin') {
        setMode('ADMIN_APP');
      } else {
        setMode('PORTAL');
      }
    };

    handleUrlChange();
    window.addEventListener('popstate', handleUrlChange);

    const handleSettingsUpdate = async () => {
      try {
        const s = await getSystemSettings();
        setSettings(s);
      } catch (e) {
        console.error("Failed to update settings:", e);
      }
    };
    window.addEventListener('settings-updated', handleSettingsUpdate);

    return () => {
      window.removeEventListener('popstate', handleUrlChange);
      window.removeEventListener('settings-updated', handleSettingsUpdate);
    };
  }, []);

  const changeMode = (newMode: SystemMode) => {
    setMode(newMode);
    const url = new URL(window.location.href);

    if (newMode === 'STUDENT_APP') {
      url.searchParams.set('app', 'student');
      window.history.pushState({}, '', url);
    } else if (newMode === 'ADMIN_APP') {
      url.searchParams.set('app', 'admin');
      window.history.pushState({}, '', url);
    } else {
      url.searchParams.delete('app');
      window.history.pushState({}, '', url);
    }
  };

  const handleLogin = async (e: React.FormEvent, targetRole: 'user' | 'admin') => {
    e.preventDefault();
    setLoginError('');

    if (!username.trim()) {
      setLoginError('请输入账号/姓名');
      return;
    }

    try {
      // --- Admin Login ---
      if (targetRole === 'admin') {
        if (!password) {
          setLoginError('请输入密码 (或子管理员身份证号)');
          return;
        }

        const adminUser = await loginAdmin(username.trim(), password.trim());
        if (adminUser) {
          setCurrentUser(adminUser);
        } else {
          setLoginError('登录失败：账号或密码错误');
        }
        return;
      } 

      // --- Student/User Login ---
      if (targetRole === 'user') {
        const timeCheck = await isReportingTimeValid();
        if (!timeCheck.valid) {
          setLoginError(timeCheck.message || '当前不在报备时间内');
          return;
        }

        if (!loginPhone.trim()) {
          setLoginError('请输入手机号码');
          return;
        }

        const user = validateReporter(username.trim(), loginPhone.trim());

        if (user) {
          setCurrentUser(user);
        } else {
          setLoginError('登录失败：请输入有效的11位手机号码');
        }
      }
    } catch (err) {
      console.error("Login Error:", err);
      setLoginError('系统错误，请重试');
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setUsername('');
    setLoginPhone('');
    setPassword('');
    setLoginError('');
  };

  if (loading) {
    return <div className="min-h-screen bg-white flex items-center justify-center text-gray-400">正在初始化系统...</div>;
  }

  if (initError) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6 text-center">
        <AlertCircle size={48} className="text-red-500 mb-4" />
        <h2 className="text-xl font-bold text-gray-800 mb-2">发生错误</h2>
        <p className="text-gray-600 mb-6">{initError}</p>
        <button 
          onClick={() => window.location.reload()}
          className="bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 transition"
        >
          刷新页面
        </button>
      </div>
    );
  }

  // --- PORTAL VIEW ---
  if (mode === 'PORTAL') {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-4xl">
          <div className="text-center mb-16">
