                 </span>
                 <button 
                   onClick={handleSaveSettings}
                   className="flex items-center gap-2 bg-[#05A7E2] text-white px-6 py-3 rounded-lg font-bold hover:bg-sky-600 transition shadow-lg shadow-blue-200"
