import { openDB, DBSchema, IDBPDatabase } from 'idb';
import { Student, Recruiter, AppUser, SystemSettings, CloudConfig } from '../types';

// --- Database Schema Definition ---
interface SchoolDB extends DBSchema {
  students: {
    key: string;
    value: Student;
    indexes: { 'by-date': string };
  };
  appUsers: {
    key: string;
    value: AppUser;
    indexes: { 'by-idCard': string };
  };
  settings: {
    key: string;
    value: any; 
  };
}

const DB_NAME = 'chengdu_school_db';
const DB_VERSION = 1;
const CLOUD_CONFIG_KEY = 'cloud_config';

// --- Mock Data ---
const MOCK_ADMIN: Recruiter = { id: 'admin-1', username: 'admin', role: 'admin' };
const ADMIN_PWD_KEY = 'admin_password';
const DEFAULT_PASSWORD = 'system123@';

// --- DB Initialization ---
let dbPromise: Promise<IDBPDatabase<SchoolDB>>;

const getDB = () => {
  if (!dbPromise) {
    dbPromise = openDB<SchoolDB>(DB_NAME, DB_VERSION, {
      upgrade(db) {
        if (!db.objectStoreNames.contains('students')) {
          const studentStore = db.createObjectStore('students', { keyPath: 'id' });
          studentStore.createIndex('by-date', 'reportTime');
        }
        if (!db.objectStoreNames.contains('appUsers')) {
          const userStore = db.createObjectStore('appUsers', { keyPath: 'id' });
          userStore.createIndex('by-idCard', 'idCard', { unique: true });
        }
        if (!db.objectStoreNames.contains('settings')) {
          db.createObjectStore('settings');
        }
      },
    }).catch(err => {
        console.error("Failed to open database", err);
        throw err;
    }) as any;
  }
  return dbPromise;
};

const generateId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

// --- Cloud Configuration Helpers ---

export const getCloudConfig = async (): Promise<CloudConfig | null> => {
  const db = await getDB();
  return (await db.get('settings', CLOUD_CONFIG_KEY)) || null;
};

export const saveCloudConfig = async (config: CloudConfig): Promise<void> => {
  const db = await getDB();
  await db.put('settings', config, CLOUD_CONFIG_KEY);
  window.dispatchEvent(new Event('settings-updated'));
};

/**
 * Generic Request Handler
 * - Firebase: Uses path-based REST API
 * - Http File: Not used directly (uses monolithic sync instead)
 */
const cloudRequest = async (path: string, method: string = 'GET', body?: any) => {
  const config = await getCloudConfig();
  if (!config || !config.enabled || !config.dbUrl) {
    throw new Error("Cloud not configured");
  }

  // Only for Firebase mode
  if (config.type !== 'firebase') return null;

  let url = `${config.dbUrl}/${path}.json`;
  if (config.dbSecret) {
    url += `?auth=${config.dbSecret}`;
  }

  const response = await fetch(url, {
    method,
    body: body ? JSON.stringify(body) : undefined,
    headers: { 'Content-Type': 'application/json' }
  });

  if (!response.ok) {
    throw new Error(`Cloud request failed: ${response.statusText}`);
  }

  return response.json();
};

// --- HTTP FILE SYNC HELPERS ---

/**
 * Downloads the full JSON file from the server and restores it to IDB.
 */
const syncFromServer = async (config: CloudConfig): Promise<void> => {
  try {
    const headers: HeadersInit = {};
    if (config.dbSecret) {
      headers['Authorization'] = `Bearer ${config.dbSecret}`;
      headers['X-Api-Key'] = config.dbSecret;
    }

    const response = await fetch(config.dbUrl, { method: 'GET', headers });
    if (!response.ok) throw new Error(`Fetch failed: ${response.status}`);

    const data = await response.json();
    await restoreFromBackup(JSON.stringify(data), false); // Restore without refreshing page/cloud loop
  } catch (e) {
    console.error("Sync from server failed", e);
    // Do not throw, allow local usage
  }
};

/**
 * Uploads the full IDB state as a JSON file to the server.
 */
const syncToServer = async (config: CloudConfig): Promise<void> => {
  try {
    const backupJson = await getFullBackup();
    const url = config.writeUrl || config.dbUrl; // Use writeUrl if provided, else dbUrl

    const headers: HeadersInit = { 'Content-Type': 'application/json' };
    if (config.dbSecret) {
      headers['Authorization'] = `Bearer ${config.dbSecret}`;
      headers['X-Api-Key'] = config.dbSecret;
    }

    const response = await fetch(url, {
      method: 'POST', // Usually POST or PUT for file upload APIs
      body: backupJson,
      headers
    });

    if (!response.ok) throw new Error(`Upload failed: ${response.status}`);
  } catch (e) {
    console.error("Sync to server failed", e);
  }
};

// --- Student Operations ---

export const getStudents = async (): Promise<Student[]> => {
  const config = await getCloudConfig();

  // Mode: Firebase
  if (config?.enabled && config.type === 'firebase') {
    try {
      const data = await cloudRequest('students');
      if (!data) return [];
      const students = Object.values(data) as Student[];
      return students.sort((a, b) => new Date(b.reportTime).getTime() - new Date(a.reportTime).getTime());
    } catch (e) {
      console.warn("Firebase fetch failed", e);
    }
  }

  // Mode: HTTP File (Sync then Read Local)
  if (config?.enabled && config.type === 'http_file') {
    // We try to sync from server to ensure fresh data, but don't block too long?
    // For simplicity in this demo, we await. In prod, maybe background.
    await syncFromServer(config);
  }

  // Read Local (IDB) - acts as Source of Truth for HTTP File mode after sync, or Cache for Firebase
  const db = await getDB();
  const students = await db.getAll('students');
  return students.sort((a, b) => new Date(b.reportTime).getTime() - new Date(a.reportTime).getTime());
};

export const saveStudent = async (student: Omit<Student, 'id' | 'reportTime'>): Promise<Student> => {
  const newStudent: Student = {
    ...student,
    id: generateId(),
    reportTime: new Date().toISOString(),
  };

  const config = await getCloudConfig();

  // 1. Save to Local IDB first (Optimistic UI)
  const db = await getDB();
  await db.put('students', newStudent);

  // 2. Sync to Cloud
  if (config?.enabled) {
    if (config.type === 'firebase') {
      await cloudRequest(`students/${newStudent.id}`, 'PUT', newStudent);
    } else if (config.type === 'http_file') {
      // For file mode, we must push the WHOLE state
      await syncToServer(config);
    }
  }

  window.dispatchEvent(new Event('students-updated'));
  return newStudent;
};

export const deleteStudent = async (id: string): Promise<void> => {
  const config = await getCloudConfig();

  // 1. Delete Local
  const db = await getDB();
  await db.delete('students', id);

  // 2. Sync Cloud
  if (config?.enabled) {
    if (config.type === 'firebase') {
      await cloudRequest(`students/${id}`, 'DELETE');
    } else if (config.type === 'http_file') {
      await syncToServer(config);
    }
  }

  window.dispatchEvent(new Event('students-updated'));
};

