export const isReportingTimeValid = async (): Promise<{ valid: boolean; message?: string }> => {
  try {
    const settings = await getSystemSettings();
    const now = new Date().getTime();

    const startStr = settings.reportingStartTime;
    const endStr = settings.reportingEndTime;

    const hasStart = startStr && startStr.trim() !== '';
    const hasEnd = endStr && endStr.trim() !== '';

    if (!hasStart && !hasEnd) {
      return { valid: false, message: '系统未开启：后台暂未配置报备时间。' };
    }

    if (hasStart) {
      const startDate = new Date(startStr);
      if (!isNaN(startDate.getTime()) && now < startDate.getTime()) {
        return { valid: false, message: `系统未开放。开放时间: ${startDate.toLocaleString()}` };
      }
    }

    if (hasEnd) {
      const endDate = new Date(endStr);
      if (!isNaN(endDate.getTime()) && now > endDate.getTime()) {
        return { valid: false, message: `报备已截止。截止时间: ${endDate.toLocaleString()}` };
      }
    }

    return { valid: true };
  } catch (e) {
    return { valid: false, message: "时间校验失败" };
  }
};

// --- Authentication Logic ---

export const verifyAdminPassword = async (inputPassword: string): Promise<boolean> => {
  const config = await getCloudConfig();
  let storedPwd;

  if (config?.enabled) {
     // For Http File, getSystemSettings already synced the DB, so we can just read local
     // For Firebase, we might need a fetch
     if (config.type === 'firebase') {
        storedPwd = await cloudRequest(ADMIN_PWD_KEY);
     } else {
        const db = await getDB();
        storedPwd = await db.get('settings', ADMIN_PWD_KEY);
     }
  } else {
    const db = await getDB();
    storedPwd = await db.get('settings', ADMIN_PWD_KEY);
  }

  if (!storedPwd) {
    return inputPassword === DEFAULT_PASSWORD;
  }

  return inputPassword === storedPwd;
};

export const changeAdminPassword = async (newPassword: string): Promise<void> => {
  const db = await getDB();
  await db.put('settings', newPassword, ADMIN_PWD_KEY);

  const config = await getCloudConfig();
  if (config?.enabled) {
    if (config.type === 'firebase') {
      await cloudRequest(ADMIN_PWD_KEY, 'PUT', newPassword);
    } else if (config.type === 'http_file') {
      await syncToServer(config);
    }
  }
};

export const loginAdmin = async (username: string, passwordOrIdCard: string): Promise<Recruiter | null> => {
  if (username === 'admin') {
    const isValid = await verifyAdminPassword(passwordOrIdCard);
    return isValid ? MOCK_ADMIN : null;
  }

  const users = await getAppUsers(); 
  const user = users.find(u => u.idCard === passwordOrIdCard && u.username === username);

  if (user && user.status === 'active') {
    return {
      id: user.id,
      username: user.username,
      role: 'admin'
    };
  }

  return null;
};

export const validateReporter = (username: string, phoneNumber: string): Recruiter | null => {
  if (!username) return null;
  const phoneRegex = /^1[3-9]\d{9}$/;

  if (!phoneRegex.test(phoneNumber)) {
    return null;
  }

  return {
    id: phoneNumber,
    username: username,
    role: 'user'
  };
};

// --- Backup & Restore ---

export const getFullBackup = async (): Promise<string> => {
  const db = await getDB();
  const students = await db.getAll('students');
  const appUsers = await db.getAll('appUsers');
  const settings = await db.get('settings', 'system_config');
  const password = await db.get('settings', ADMIN_PWD_KEY);
  const cloudConfig = await db.get('settings', CLOUD_CONFIG_KEY);

  const backup = {
    students,
    appUsers,
    settings: settings || null,
    password: password || null, // Include password in file sync
    cloudConfig: cloudConfig || null,
    timestamp: new Date().toISOString(),
    version: '2.0',
    note: 'Chengdu Urban Construction School Data Backup'
  };
  return JSON.stringify(backup, null, 2);
};

// internal helper to restore without circular sync
const restoreFromBackupInternal = async (db: IDBPDatabase<SchoolDB>, data: any) => {
    const tx = db.transaction(['students', 'appUsers', 'settings'], 'readwrite');

    // Clear existing
    await tx.objectStore('students').clear();
    await tx.objectStore('appUsers').clear();

    // Restore Students
    if (Array.isArray(data.students)) {
      for (const s of data.students) {
        await tx.objectStore('students').put(s);
      }
    }

    // Restore Users
    if (Array.isArray(data.appUsers)) {
      for (const u of data.appUsers) {
        await tx.objectStore('appUsers').put(u);
      }
    }

    // Restore Settings
    if (data.settings) {
      await tx.objectStore('settings').put(data.settings, 'system_config');
    }

    // Restore Password
    if (data.password) {
        await tx.objectStore('settings').put(data.password, ADMIN_PWD_KEY);
    }

    // Restore Cloud Config (be careful not to overwrite with null if we are running from cloud)
    if (data.cloudConfig) {
      await tx.objectStore('settings').put(data.cloudConfig, CLOUD_CONFIG_KEY);
    }

    await tx.done;
}

export const restoreFromBackup = async (jsonString: string, shouldSyncUp: boolean = true): Promise<{ success: boolean; message: string }> => {
  try {
    const data = JSON.parse(jsonString);
    if (!data || typeof data !== 'object') {
      return { success: false, message: '无效的文件格式' };
    }

    const db = await getDB();
    await restoreFromBackupInternal(db, data);

    window.dispatchEvent(new Event('students-updated'));
    window.dispatchEvent(new Event('settings-updated'));

    // If this restore came from a user upload, we might want to sync it UP to the cloud file
    if (shouldSyncUp) {
        const config = await getCloudConfig();
        if (config?.enabled && config.type === 'http_file') {
            await syncToServer(config);
        }
    }

    return { success: true, message: '数据恢复成功' };
  } catch (error) {
    console.error("Restore error", error);
    return { success: false, message: '恢复失败: ' + (error as Error).message };
  }
};

export const exportToCSV = async (data?: Student[]): Promise<void> => {
  try {
    const students = data || await getStudents();

    if (students.length === 0) {
      alert("暂无数据可导出");
      return;
    }

    const headers = ["ID", "姓名", "电话", "电话归属", "报备时间", "填报人", "填报人电话"];
    const csvContent = [
      headers.join(","),
      ...students.map(s => [
        s.id,
        s.name,
        s.phoneNumber,
        s.contactType === 'student' ? '学生本人' : '家长',
        new Date(s.reportTime).toLocaleString(),
        s.recruiterName || s.recruiterId,
        s.recruiterPhone || s.recruiterId
      ].join(","))
    ].join("\n");

    const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    const prefix = data ? '筛选报备数据' : '全部报备数据';
    link.setAttribute("download", `${prefix}_${new Date().toISOString().slice(0,10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  } catch (e) {
    console.error("Export Error", e);
    alert("导出失败：无法获取数据。");
  }
};

import React, { useEffect, useState, useRef } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer 
} from 'recharts';
import { Download, Sparkles, RefreshCw, LogOut, Users, Search, Lock, X, Clock, Plus, Trash2, Check, Image as ImageIcon, Upload, Database, UploadCloud, DownloadCloud, Globe, Link as LinkIcon, AlertCircle, Server } from 'lucide-react';
import { 
  getStudents, exportToCSV, verifyAdminPassword, changeAdminPassword, 
  getAppUsers, saveAppUser, deleteAppUser,
  getSystemSettings, saveSystemSettings, deleteStudent,
  getFullBackup, restoreFromBackup,
  getCloudConfig, saveCloudConfig
} from '../services/dataService';
import { analyzeRecruitmentData } from '../services/geminiService';
import { Student, AnalysisResult, AppUser, SystemSettings, Recruiter, CloudConfig } from '../types';

interface Props {
  user: Recruiter;
  onLogout: () => void;
}

type Tab = 'DASHBOARD' | 'USERS' | 'SETTINGS';

const DEFAULT_LOGO = "https://pic1.imgdb.cn/item/69383a2df9354404e341391f.jpg";

const AdminDashboard: React.FC<Props> = ({ user, onLogout }) => {
  const [activeTab, setActiveTab] = useState<Tab>('DASHBOARD');
  const [students, setStudents] = useState<Student[]>([]);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [analyzing, setAnalyzing] = useState<false>(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Password Modal
  const [showPwdModal, setShowPwdModal] = useState(false);
  const [oldPwd, setOldPwd] = useState('');
  const [newPwd, setNewPwd] = useState('');
  const [pwdError, setPwdError] = useState('');
  const [pwdSuccess, setPwdSuccess] = useState('');

  // User Management State
  const [appUsers, setAppUsers] = useState<AppUser[]>([]);
  const [showUserModal, setShowUserModal] = useState(false);
  const [userFormName, setUserFormName] = useState('');
  const [userFormIdCard, setUserFormIdCard] = useState('');
  const [userFormError, setUserFormError] = useState('');

  // Settings State
  const [settings, setSettings] = useState<SystemSettings>({ reportingStartTime: null, reportingEndTime: null, logoUrl: '' });
  const [cloudConfig, setCloudConfig] = useState<CloudConfig>({ type: 'firebase', dbUrl: '', dbSecret: '', enabled: false });
  const [settingsSaved, setSettingsSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const backupInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    // Wrap initial loads in a safe function
    const init = async () => {
      try {
        await loadSettings(); 
        await loadData(); 
        if (user.username === 'admin') {
          await loadUsers();
        }
      } catch (e) {
        console.error("Dashboard init error:", e);
      }
    };
    init();

    // Event listener for real-time updates (Same Tab)
    const handleDataUpdate = () => {
      loadData().catch(console.error);
    };
    const handleSettingsUpdate = () => {
      loadSettings().catch(console.error);
    }

    window.addEventListener('students-updated', handleDataUpdate);
    window.addEventListener('settings-updated', handleSettingsUpdate);

    return () => {
      window.removeEventListener('students-updated', handleDataUpdate);
      window.removeEventListener('settings-updated', handleSettingsUpdate);
    };
  }, [user]);

  const loadData = async () => {
    try {
      const data = await getStudents();
      const allStudents = Array.isArray(data) ? data : [];
      if (user.username === 'admin') {
        setStudents(allStudents);
      } else {
        setStudents(allStudents.filter(s => s.recruiterId === user.id));
      }
    } catch (e) {
      console.error("Failed to load students", e);
    }
  };

  const loadUsers = async () => {
    try {
      const users = await getAppUsers();
      setAppUsers(Array.isArray(users) ? users : []);
    } catch (e) {
      console.error("Failed to load users", e);
    }
  };

  const loadSettings = async () => {
    try {
      const s = await getSystemSettings();
      setSettings(s || { reportingStartTime: null, reportingEndTime: null, logoUrl: '' });

      const c = await getCloudConfig();
      if (c) setCloudConfig(prev => ({...prev, ...c})); // Merge to keep defaults
    } catch (e) {
      console.error("Failed to load settings", e);
    }
  };

  // --- Handlers ---

  const handleAnalysis = async () => {
    setAnalyzing(true);
    try {
      const result = await analyzeRecruitmentData(students);
      setAnalysis(result);
    } catch (e) {
      console.error(e);
    } finally {
      setAnalyzing(false);
    }
  };

  const handleDeleteStudent = async (id: string) => {
    if (confirm('确定要删除这条报备数据吗？此操作不可恢复。')) {
      try {
        await deleteStudent(id);
      } catch (e) {
        alert("删除失败，请重试");
        console.error(e);
      }
    }
  };

  const handlePasswordChange = async (e: React.FormEvent) => {
    e.preventDefault();
    setPwdError('');
    setPwdSuccess('');

    try {
      const isValid = await verifyAdminPassword(oldPwd);
      if (!isValid) {
        setPwdError('原密码错误');
        return;
      }
      if (newPwd.length < 6) {
        setPwdError('新密码长度不能少于6位');
        return;
      }

      await changeAdminPassword(newPwd);
      setPwdSuccess('密码修改成功');
      setTimeout(() => {
        setShowPwdModal(false);
        setOldPwd('');
        setNewPwd('');
        setPwdSuccess('');
      }, 1500);
    } catch (e) {
      setPwdError("操作失败");
      console.error(e);
    }
  };

  const handleAddUser = async (e: React.FormEvent) => {
    e.preventDefault();
    setUserFormError('');

    if (!userFormName || !userFormIdCard) {
      setUserFormError('请填写完整信息');
      return;
    }

    try {
      await saveAppUser({
        username: userFormName,
        idCard: userFormIdCard,
        status: 'active'
      });
      setShowUserModal(false);
      setUserFormName('');
      setUserFormIdCard('');
      await loadUsers();
    } catch (err: any) {
      setUserFormError(err.message || '添加失败');
    }
  };

  const handleDeleteUser = async (id: string) => {
    if (confirm('确定要删除该管理员账号吗？删除后该用户将无法登录后台。')) {
      try {
        await deleteAppUser(id);
        await loadUsers();
      } catch (e) {
        alert("删除失败");
        console.error(e);
      }
    }
  };

  const handleSaveSettings = async () => {
    try {
      await saveSystemSettings(settings);
      await saveCloudConfig(cloudConfig);

      setSettingsSaved(true);
      setTimeout(() => setSettingsSaved(false), 2000);

      await loadData();
    } catch (e) {
      alert("保存失败");
      console.error(e);
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.size > 1024 * 1024) {
      alert("为了保证系统性能，图片大小不能超过 1MB。");
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      setSettings(prev => ({ ...prev, logoUrl: base64String }));
    };
    reader.readAsDataURL(file);
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
  };

  // --- Backup & Restore Handlers ---

  const handleExportBackup = async () => {
    try {
      const jsonString = await getFullBackup();
      const blob = new Blob([jsonString], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      const dateStr = new Date().toISOString().split('T')[0];
      link.download = `school_db_backup_${dateStr}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } catch (e) {
      alert("导出备份失败");
      console.error(e);
    }
  };

  const handleImportBackup = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!confirm("高风险操作：恢复备份将完全覆盖当前的【所有数据】。\n\n建议在恢复前先导出当前数据作为备份。\n\n确定要继续吗？")) {
      if (backupInputRef.current) backupInputRef.current.value = '';
      return;
    }

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const content = e.target?.result as string;
        const result = await restoreFromBackup(content);
        if (result.success) {
          alert("数据恢复成功！系统将刷新以应用更改。");
          window.location.reload();
        } else {
          alert(`恢复失败: ${result.message}`);
        }
      } catch (err) {
        alert("恢复过程中发生错误");
        console.error(err);
      }
    };
    reader.readAsText(file);
    if (backupInputRef.current) backupInputRef.current.value = '';
  };

  // --- Helpers for Sharing ---
  const getShareLink = () => {
    if (!cloudConfig.dbUrl) return '';
    const baseUrl = window.location.href.split('?')[0];
    const params = new URLSearchParams();
    params.set('app', 'student');
    // We only share the READ URL for safety in the link usually, but for this demo we share config
    // We encode the whole config slightly obscured
    params.set('sync_url', encodeURIComponent(cloudConfig.dbUrl));
    if (cloudConfig.writeUrl) {
        params.set('sync_write', encodeURIComponent(cloudConfig.writeUrl));
    }
    if (cloudConfig.dbSecret) {
        params.set('sync_key', encodeURIComponent(cloudConfig.dbSecret));
    }
    // Also pass the type
    if (cloudConfig.type === 'http_file') {
        params.set('sync_type', 'file');
    }
    return `${baseUrl}?${params.toString()}`;
  };

  const copyShareLink = () => {
    const link = getShareLink();
    if (link) {
      navigator.clipboard.writeText(link);
      alert("H5 报备端链接已复制！发送给招生老师即可自动连接数据库。");
    }
  };

  // --- Chart Data ---
  const chartData = React.useMemo(() => {
    if (!Array.isArray(students)) return [];
    const last7Days = [...Array(7)].map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      return {
        date: date.slice(5),
        count: students.filter(s => s.reportTime && s.reportTime.startsWith(date)).length
      };
    });
  }, [students]);

  const filteredStudents = Array.isArray(students) ? students.filter(s => 
    (s.name || '').includes(searchTerm) || 
    (s.phoneNumber || '').includes(searchTerm)
  ) : [];

  return (
    <div className="min-h-screen bg-white flex flex-col">
      {/* Top Navbar */}
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-20">
            <div className="flex items-center gap-4">
              <img src={settings.logoUrl || DEFAULT_LOGO} alt="Logo" className="h-12 w-12 object-contain" />
              <div>
                <h1 className="text-2xl font-bold text-[#05A7E2] leading-none">成都城市建设技工学校</h1>
                <p className="text-sm text-gray-500 mt-1">招生管理后台 ({user.username})</p>
              </div>
            </div>
            <div className="flex items-center gap-4">
              {user.username === 'admin' && (
                <button 
                  onClick={() => setShowPwdModal(true)}
                  className="flex items-center gap-2 text-sm font-medium text-gray-600 hover:text-school-600 transition"
                >
                  <Lock size={16} /> 修改密码
                </button>
              )}
              <div className="h-6 w-px bg-gray-200"></div>
              <button
                onClick={onLogout}
                className="flex items-center gap-2 text-sm font-medium text-gray-600 hover:text-red-600 transition"
              >
                <LogOut size={16} /> 退出
              </button>
            </div>
          </div>

          {/* Navigation Tabs */}
          <div className="flex space-x-8 -mb-px overflow-x-auto">
            <button
              onClick={() => setActiveTab('DASHBOARD')}
              className={`pb-4 px-1 border-b-2 font-medium text-sm transition ${activeTab === 'DASHBOARD' ? 'border-school-600 text-school-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
            >
              数据报表
            </button>
            {user.username === 'admin' && (
              <>
                <button
                  onClick={() => setActiveTab('USERS')}
                  className={`pb-4 px-1 border-b-2 font-medium text-sm transition ${activeTab === 'USERS' ? 'border-school-600 text-school-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                >
                  用户管理
                </button>
                <button
                  onClick={() => setActiveTab('SETTINGS')}
                  className={`pb-4 px-1 border-b-2 font-medium text-sm transition ${activeTab === 'SETTINGS' ? 'border-school-600 text-school-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                >
                  系统设置
                </button>
              </>
            )}
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">

        {/* --- DASHBOARD TAB --- */}
        {activeTab === 'DASHBOARD' && (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
             <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white rounded-xl shadow-lg border border-gray-100 p-6">
                <h3 className="text-sm font-medium text-gray-500">
                  {user.username === 'admin' ? '总报备人数' : '我的报备人数'}
                </h3>
                <div className="mt-2 flex items-baseline gap-2">
                  <span className="text-4xl font-extrabold text-gray-900">{students.length}</span>
                  <span className="text-sm text-gray-500">人</span>
                </div>
                <div className="mt-4">
                  <button 
                    onClick={() => exportToCSV(filteredStudents).catch(console.error)}
                    className="w-full flex items-center justify-center gap-2 bg-gray-50 border border-gray-200 text-gray-700 hover:bg-gray-100 px-4 py-2 rounded-lg text-sm font-medium transition"
                  >
                    <Download size={16} /> 导出所有报表 (.csv)
                  </button>
                </div>
              </div>

              <div className="bg-gradient-to-br from-[#05A7E2] to-blue-700 rounded-xl shadow-lg p-6 text-white md:col-span-2 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-6 opacity-10">
                  <Sparkles className="w-40 h-40" />
                </div>
                <div className="relative z-10 h-full flex flex-col justify-between">
                  <div className="flex justify-between items-start">
                    <div>
                      <h3 className="text-lg font-bold flex items-center gap-2">
                        <Sparkles className="w-5 h-5 text-yellow-300" /> AI 智能分析
                      </h3>
                      <p className="text-blue-100 text-sm mt-1">基于实时数据的招生趋势洞察</p>
                    </div>
                    <button 
                      onClick={handleAnalysis}
                      disabled={analyzing}
                      className={`px-4 py-2 rounded-lg text-sm font-medium backdrop-blur-sm bg-white/20 hover:bg-white/30 transition border border-white/30 ${analyzing ? 'opacity-70 cursor-wait' : ''}`}
                    >
                      {analyzing ? '分析中...' : '生成分析报告'}
                    </button>
                  </div>
                  <div className="mt-4 bg-black/20 rounded-lg p-4 backdrop-blur-md min-h-[100px]">
                    {analysis ? (
                      <div className="space-y-2 text-sm">
                        <p><span className="font-bold text-yellow-300">摘要:</span> {analysis.summary}</p>
                        <p><span className="font-bold text-yellow-300">趋势:</span> {analysis.trend}</p>
                        <p><span className="font-bold text-yellow-300">建议:</span> {analysis.recommendation}</p>
                      </div>
                    ) : (
                      <p className="text-blue-200 text-sm italic flex items-center justify-center h-full">点击右上角按钮生成智能分析...</p>
                    )}
                  </div>
                </div>
              </div>
            </div>
            {/* ... Chart and Table sections unchanged ... */}
             <div className="bg-white rounded-xl shadow-lg border border-gray-100 p-6">
              <h3 className="text-lg font-bold text-gray-800 mb-6">近7日报名趋势</h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                    <XAxis dataKey="date" tick={{fontSize: 12, fill: '#6b7280'}} axisLine={false} tickLine={false} />
                    <YAxis allowDecimals={false} tick={{fontSize: 12, fill: '#6b7280'}} axisLine={false} tickLine={false} />
                    <RechartsTooltip cursor={{fill: '#f9fafb'}} contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} />
                    <Bar name="报备人数" dataKey="count" fill="#05A7E2" radius={[4, 4, 0, 0]} barSize={40} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-lg border border-gray-100 overflow-hidden flex flex-col">
              <div className="p-4 border-b border-gray-100 flex flex-col sm:flex-row justify-between items-center gap-4">
                <div className="flex items-center gap-2">
                   <h3 className="text-lg font-bold text-gray-800">详细报备列表</h3>
                   <button onClick={() => loadData().catch(console.error)} className="text-gray-400 hover:text-[#05A7E2]" title="刷新"><RefreshCw size={16} /></button>
                   <div className="h-4 w-px bg-gray-300 mx-1"></div>
                   <button 
                     onClick={() => exportToCSV(filteredStudents).catch(console.error)}
                     className="flex items-center gap-1 text-sm text-gray-600 hover:text-[#05A7E2] transition px-2 py-1 rounded-lg hover:bg-gray-50"
                     title="导出当前列表显示的报备数据"
                   >
                     <Download size={14} /> 导出列表
                   </button>
                </div>
                <div className="relative w-full sm:w-64">
                  <input 
                    type="text" 
                    placeholder="搜索姓名/电话..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full pl-10 pr-4 py-2 bg-gray-50 border-0 rounded-lg focus:ring-2 focus:ring-[#05A7E2] focus:bg-white transition outline-none text-sm text-gray-900 placeholder-gray-400"
                  />
                  <Search className="absolute left-3 top-2.5 text-gray-400 w-4 h-4" />
                </div>
              </div>

              <div className="overflow-x-auto custom-scrollbar">
                <table className="min-w-full divide-y divide-gray-100">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">姓名</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">联系电话</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">归属</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">报备时间</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">填报人</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">填报人手机</th>
                      {user.role === 'admin' && (
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">操作</th>
                      )}
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-100">
                    {filteredStudents.length > 0 ? (
                      filteredStudents.map((student) => (
                        <tr key={student.id} className="hover:bg-gray-50 transition">
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{student.name}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{student.phoneNumber}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm">
                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${student.contactType === 'student' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>
                              {student.contactType === 'student' ? '学生' : '家长'}
                            </span>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{new Date(student.reportTime).toLocaleString()}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{student.recruiterName || student.recruiterId}</td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{student.recruiterPhone || '-'}</td>
                          {user.role === 'admin' && (
                            <td className="px-6 py-4 whitespace-nowrap text-right text-sm">
                              <button 
                                onClick={() => handleDeleteStudent(student.id)}
                                className="text-gray-400 hover:text-red-600 transition"
                                title="删除此记录"
                              >
                                <Trash2 size={16} />
                              </button>
                            </td>
                          )}
                        </tr>
                      ))
                    ) : (
                      <tr><td colSpan={user.role === 'admin' ? 7 : 6} className="px-6 py-12 text-center text-sm text-gray-500">没有找到匹配的数据</td></tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {/* --- USERS TAB --- */}
        {activeTab === 'USERS' && (
          <div className="bg-white rounded-xl shadow-lg border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-300">
