export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import StudentForm from './components/StudentForm';
import AdminDashboard from './components/AdminDashboard';
import { Recruiter, SystemSettings } from './types';
import { loginAdmin, validateReporter, getSystemSettings, isReportingTimeValid, saveCloudConfig } from './services/dataService';
import { School, User, ChevronRight, Smartphone, Monitor, Lock, Clock, AlertCircle } from 'lucide-react';

type SystemMode = 'PORTAL' | 'STUDENT_APP' | 'ADMIN_APP';

const DEFAULT_LOGO = "https://pic1.imgdb.cn/item/69383a2df9354404e341391f.jpg";

const App: React.FC = () => {
  // --- 1. Top-Level Hooks (Must always run in the same order) ---
  const [mode, setMode] = useState<SystemMode>('PORTAL');
  const [currentUser, setCurrentUser] = useState<Recruiter | null>(null);
  const [settings, setSettings] = useState<SystemSettings>({ reportingStartTime: null, reportingEndTime: null, logoUrl: '' });
  const [loading, setLoading] = useState(true);
  const [initError, setInitError] = useState<string>('');
  const [configSuccess, setConfigSuccess] = useState('');

  const [timeCheck, setTimeCheck] = useState<{valid: boolean, message?: string} | null>(null);

  // Authentication State
  const [username, setUsername] = useState('');
  const [loginPhone, setLoginPhone] = useState('');
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState('');

  // --- 2. Effects ---

  // Initial Data Load
  useEffect(() => {
    const init = async () => {
      try {
        // Check for URL-based configuration (for sharing DB connection)
        const params = new URLSearchParams(window.location.search);
        const syncUrl = params.get('sync_url');
        const syncKey = params.get('sync_key');
        const syncType = params.get('sync_type');
        const syncWrite = params.get('sync_write');

        if (syncUrl) {
          const decodedUrl = decodeURIComponent(syncUrl);
          const decodedKey = syncKey ? decodeURIComponent(syncKey) : undefined;
          const decodedWrite = syncWrite ? decodeURIComponent(syncWrite) : undefined;

          const type: 'firebase' | 'http_file' = syncType === 'file' ? 'http_file' : 'firebase';

          await saveCloudConfig({
            type,
            dbUrl: decodedUrl,
            writeUrl: decodedWrite,
            dbSecret: decodedKey,
            enabled: true
          });
          setConfigSuccess("已成功连接到远程数据库");
          // Clear params from URL to look cleaner
          const newUrl = window.location.protocol + "//" + window.location.host + window.location.pathname + "?app=student";
          window.history.replaceState({path: newUrl}, '', newUrl);
        }

        const s = await getSystemSettings();
        setSettings(s);
      } catch (e) {
        console.error("Initialization error:", e);
        setInitError("系统初始化失败：无法连接本地数据库。请检查浏览器隐私设置或尝试刷新页面。");
      } finally {
        setLoading(false);
      }
    };
    init();

    const handleUrlChange = () => {
      const params = new URLSearchParams(window.location.search);
      const appParam = params.get('app');
      if (appParam === 'student') {
        setMode('STUDENT_APP');
      } else if (appParam === 'admin') {
        setMode('ADMIN_APP');
      } else {
        setMode('PORTAL');
      }
    };

    handleUrlChange();
    window.addEventListener('popstate', handleUrlChange);

    const handleSettingsUpdate = async () => {
      try {
        const s = await getSystemSettings();
        setSettings(s);
      } catch (e) {
        console.error("Failed to update settings:", e);
      }
    };
    window.addEventListener('settings-updated', handleSettingsUpdate);

    return () => {
      window.removeEventListener('popstate', handleUrlChange);
      window.removeEventListener('settings-updated', handleSettingsUpdate);
    };
  }, []);

  // Separate effect for time checking
  useEffect(() => {
    const checkTime = () => {
       isReportingTimeValid()
         .then(res => setTimeCheck(res))
         .catch(err => {
            console.error("Time check failed", err);
            setTimeCheck({valid: false, message: "无法连接数据库校验时间"});
         });
    };

    checkTime();
    window.addEventListener('settings-updated', checkTime);
    return () => window.removeEventListener('settings-updated', checkTime);
  }, []);

  // --- 3. Handlers ---

  const changeMode = (newMode: SystemMode) => {
    setMode(newMode);
    const url = new URL(window.location.href);

    if (newMode === 'STUDENT_APP') {
      url.searchParams.set('app', 'student');
      window.history.pushState({}, '', url);
    } else if (newMode === 'ADMIN_APP') {
      url.searchParams.set('app', 'admin');
      window.history.pushState({}, '', url);
    } else {
      url.searchParams.delete('app');
      window.history.pushState({}, '', url);
    }
  };

  const handleLogin = async (e: React.FormEvent, targetRole: 'user' | 'admin') => {
    e.preventDefault();
    setLoginError('');

    if (!username.trim()) {
      setLoginError('请输入账号/姓名');
      return;
    }

    try {
      // --- Admin Login ---
      if (targetRole === 'admin') {
        if (!password) {
          setLoginError('请输入密码 (或子管理员身份证号)');
          return;
        }

        const adminUser = await loginAdmin(username.trim(), password.trim());
        if (adminUser) {
          setCurrentUser(adminUser);
        } else {
