// internal helper to restore without circular sync
const restoreFromBackupInternal = async (db: IDBPDatabase<SchoolDB>, data: any) => {
    const tx = db.transaction(['students', 'appUsers', 'settings'], 'readwrite');

    // Clear existing
    await tx.objectStore('students').clear();
    await tx.objectStore('appUsers').clear();

    // Restore Students
    if (Array.isArray(data.students)) {
      for (const s of data.students) {
        await tx.objectStore('students').put(s);
      }
    }

    // Restore Users
    if (Array.isArray(data.appUsers)) {
      for (const u of data.appUsers) {
        await tx.objectStore('appUsers').put(u);
      }
    }

    // Restore Settings
    if (data.settings) {
      await tx.objectStore('settings').put(data.settings, 'system_config');
    }

    // Restore Password
    if (data.password) {
        await tx.objectStore('settings').put(data.password, ADMIN_PWD_KEY);
    }

    // Restore Cloud Config (be careful not to overwrite with null if we are running from cloud)
    if (data.cloudConfig) {
      await tx.objectStore('settings').put(data.cloudConfig, CLOUD_CONFIG_KEY);
    }

    await tx.done;
}

export const restoreFromBackup = async (jsonString: string, shouldSyncUp: boolean = true): Promise<{ success: boolean; message: string }> => {
  try {
    const data = JSON.parse(jsonString);
    if (!data || typeof data !== 'object') {
      return { success: false, message: '无效的文件格式' };
    }

    const db = await getDB();
    await restoreFromBackupInternal(db, data);

    window.dispatchEvent(new Event('students-updated'));
    window.dispatchEvent(new Event('settings-updated'));

    // If this restore came from a user upload, we might want to sync it UP to the cloud file
    if (shouldSyncUp) {
        const config = await getCloudConfig();
        if (config?.enabled && config.type === 'http_file') {
            await syncToServer(config);
        }
    }

    return { success: true, message: '数据恢复成功' };
  } catch (error) {
    console.error("Restore error", error);
    return { success: false, message: '恢复失败: ' + (error as Error).message };
  }
};

