    }

    const headers = ["ID", "姓名", "电话", "电话归属", "报备时间", "填报人", "填报人电话"];
    const csvContent = [
      headers.join(","),
      ...students.map(s => [
        s.id,
        s.name,
        s.phoneNumber,
        s.contactType === 'student' ? '学生本人' : '家长',
        new Date(s.reportTime).toLocaleString(),
        s.recruiterName || s.recruiterId,
        s.recruiterPhone || s.recruiterId
      ].join(","))
    ].join("\n");

    const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    const prefix = data ? '筛选报备数据' : '全部报备数据';
    link.setAttribute("download", `${prefix}_${new Date().toISOString().slice(0,10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  } catch (e) {
    console.error("Export Error", e);
    alert("导出失败：无法获取数据。");
  }
};

import React, { useEffect, useState, useRef } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer 
} from 'recharts';
import { Download, Sparkles, RefreshCw, LogOut, Users, Search, Lock, X, Clock, Plus, Trash2, Check, Image as ImageIcon, Upload, Database, UploadCloud, DownloadCloud, Globe, Link as LinkIcon, AlertCircle, Server } from 'lucide-react';
import { 
  getStudents, exportToCSV, verifyAdminPassword, changeAdminPassword, 
  getAppUsers, saveAppUser, deleteAppUser,
  getSystemSettings, saveSystemSettings, deleteStudent,
  getFullBackup, restoreFromBackup,
  getCloudConfig, saveCloudConfig
} from '../services/dataService';
import { analyzeRecruitmentData } from '../services/geminiService';
import { Student, AnalysisResult, AppUser, SystemSettings, Recruiter, CloudConfig } from '../types';

interface Props {
  user: Recruiter;
  onLogout: () => void;
}

type Tab = 'DASHBOARD' | 'USERS' | 'SETTINGS';

const DEFAULT_LOGO = "https://pic1.imgdb.cn/item/69383a2df9354404e341391f.jpg";

const AdminDashboard: React.FC<Props> = ({ user, onLogout }) => {
  const [activeTab, setActiveTab] = useState<Tab>('DASHBOARD');
  const [students, setStudents] = useState<Student[]>([]);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [analyzing, setAnalyzing] = useState<false>(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Password Modal
  const [showPwdModal, setShowPwdModal] = useState(false);
  const [oldPwd, setOldPwd] = useState('');
  const [newPwd, setNewPwd] = useState('');
  const [pwdError, setPwdError] = useState('');
  const [pwdSuccess, setPwdSuccess] = useState('');

  // User Management State
  const [appUsers, setAppUsers] = useState<AppUser[]>([]);
  const [showUserModal, setShowUserModal] = useState(false);
  const [userFormName, setUserFormName] = useState('');
  const [userFormIdCard, setUserFormIdCard] = useState('');
  const [userFormError, setUserFormError] = useState('');

  // Settings State
  const [settings, setSettings] = useState<SystemSettings>({ reportingStartTime: null, reportingEndTime: null, logoUrl: '' });
  const [cloudConfig, setCloudConfig] = useState<CloudConfig>({ type: 'firebase', dbUrl: '', dbSecret: '', enabled: false });
  const [settingsSaved, setSettingsSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const backupInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    // Wrap initial loads in a safe function
    const init = async () => {
      try {
        await loadSettings(); 
        await loadData(); 
        if (user.username === 'admin') {
          await loadUsers();
        }
      } catch (e) {
        console.error("Dashboard init error:", e);
      }
    };
    init();

    // Event listener for real-time updates (Same Tab)
    const handleDataUpdate = () => {
      loadData().catch(console.error);
    };
    const handleSettingsUpdate = () => {
      loadSettings().catch(console.error);
    }

    window.addEventListener('students-updated', handleDataUpdate);
    window.addEventListener('settings-updated', handleSettingsUpdate);

    return () => {
      window.removeEventListener('students-updated', handleDataUpdate);
      window.removeEventListener('settings-updated', handleSettingsUpdate);
    };
  }, [user]);

  const loadData = async () => {
    try {
      const data = await getStudents();
      const allStudents = Array.isArray(data) ? data : [];
      if (user.username === 'admin') {
        setStudents(allStudents);
      } else {
        setStudents(allStudents.filter(s => s.recruiterId === user.id));
      }
    } catch (e) {
      console.error("Failed to load students", e);
    }
  };

  const loadUsers = async () => {
    try {
      const users = await getAppUsers();
      setAppUsers(Array.isArray(users) ? users : []);
    } catch (e) {
      console.error("Failed to load users", e);
    }
  };

  const loadSettings = async () => {
    try {
      const s = await getSystemSettings();
      setSettings(s || { reportingStartTime: null, reportingEndTime: null, logoUrl: '' });

      const c = await getCloudConfig();
      if (c) setCloudConfig(prev => ({...prev, ...c}));
    } catch (e) {
      console.error("Failed to load settings", e);
    }
  };

  // --- Handlers ---

  const handleAnalysis = async () => {
    setAnalyzing(true);
    try {
      const result = await analyzeRecruitmentData(students);
      setAnalysis(result);
    } catch (e) {
      console.error(e);
    } finally {
      setAnalyzing(false);
    }
  };

  const handleDeleteStudent = async (id: string) => {
    if (confirm('确定要删除这条报备数据吗？此操作不可恢复。')) {
      try {
        await deleteStudent(id);
      } catch (e) {
        alert("删除失败，请重试");
        console.error(e);
      }
    }
  };

  const handlePasswordChange = async (e: React.FormEvent) => {
    e.preventDefault();
    setPwdError('');
    setPwdSuccess('');

    try {
      const isValid = await verifyAdminPassword(oldPwd);
      if (!isValid) {
        setPwdError('原密码错误');
        return;
      }
      if (newPwd.length < 6) {
        setPwdError('新密码长度不能少于6位');
        return;
      }

      await changeAdminPassword(newPwd);
      setPwdSuccess('密码修改成功');
      setTimeout(() => {
        setShowPwdModal(false);
        setOldPwd('');
        setNewPwd('');
        setPwdSuccess('');
      }, 1500);
    } catch (e) {
      setPwdError("操作失败");
      console.error(e);
    }
  };

  const handleAddUser = async (e: React.FormEvent) => {
    e.preventDefault();
    setUserFormError('');

    if (!userFormName || !userFormIdCard) {
      setUserFormError('请填写完整信息');
      return;
    }

    try {
      await saveAppUser({
        username: userFormName,
        idCard: userFormIdCard,
        status: 'active'
      });
      setShowUserModal(false);
      setUserFormName('');
      setUserFormIdCard('');
      await loadUsers();
    } catch (err: any) {
      setUserFormError(err.message || '添加失败');
    }
  };

  const handleDeleteUser = async (id: string) => {
    if (confirm('确定要删除该管理员账号吗？删除后该用户将无法登录后台。')) {
      try {
        await deleteAppUser(id);
        await loadUsers();
      } catch (e) {
        alert("删除失败");
        console.error(e);
      }
    }
  };

  const handleSaveSettings = async () => {
    try {
      await saveSystemSettings(settings);
      await saveCloudConfig(cloudConfig);

      setSettingsSaved(true);
      setTimeout(() => setSettingsSaved(false), 2000);

      await loadData();
    } catch (e) {
      alert("保存失败");
      console.error(e);
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.size > 1024 * 1024) {
      alert("为了保证系统性能，图片大小不能超过 1MB。");
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      setSettings(prev => ({ ...prev, logoUrl: base64String }));
    };
    reader.readAsDataURL(file);
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
  };

  // --- Backup & Restore Handlers ---

  const handleExportBackup = async () => {
    try {
      const jsonString = await getFullBackup();
      const blob = new Blob([jsonString], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      const dateStr = new Date().toISOString().split('T')[0];
      link.download = `school_db_backup_${dateStr}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } catch (e) {
      alert("导出备份失败");
      console.error(e);
    }
  };

  const handleImportBackup = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!confirm("高风险操作：恢复备份将完全覆盖当前的【所有数据】。\n\n建议在恢复前先导出当前数据作为备份。\n\n确定要继续吗？")) {
      if (backupInputRef.current) backupInputRef.current.value = '';
      return;
    }

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const content = e.target?.result as string;
        const result = await restoreFromBackup(content);
        if (result.success) {
          alert("数据恢复成功！系统将刷新以应用更改。");
          window.location.reload();
        } else {
          alert(`恢复失败: ${result.message}`);
        }
      } catch (err) {
        alert("恢复过程中发生错误");
        console.error(err);
      }
    };
    reader.readAsText(file);
    if (backupInputRef.current) backupInputRef.current.value = '';
  };

  // --- Helpers for Sharing ---
  const getShareLink = () => {
    if (!cloudConfig.dbUrl) return '';
    const baseUrl = window.location.href.split('?')[0];
    const params = new URLSearchParams();
    params.set('app', 'student');
    params.set('sync_url', encodeURIComponent(cloudConfig.dbUrl));
    if (cloudConfig.writeUrl) {
        params.set('sync_write', encodeURIComponent(cloudConfig.writeUrl));
    }
    if (cloudConfig.dbSecret) {
        params.set('sync_key', encodeURIComponent(cloudConfig.dbSecret));
    }
    if (cloudConfig.type === 'http_file') {
        params.set('sync_type', 'file');
    }
    return `${baseUrl}?${params.toString()}`;
  };

  const copyShareLink = () => {
    const link = getShareLink();
    if (link) {
      navigator.clipboard.writeText(link);
      alert("H5 报备端链接已复制！发送给招生老师即可自动连接数据库。");
    }
  };

  // --- Chart Data ---
  const chartData = React.useMemo(() => {
    if (!Array.isArray(students)) return [];
