import { openDB, DBSchema, IDBPDatabase } from 'idb';
import { Student, Recruiter, AppUser, SystemSettings, CloudConfig } from '../types';

// --- Database Schema Definition ---
interface SchoolDB extends DBSchema {
  students: {
    key: string;
    value: Student;
    indexes: { 'by-date': string };
  };
  appUsers: {
    key: string;
    value: AppUser;
    indexes: { 'by-idCard': string };
  };
  settings: {
    key: string;
    value: any; 
  };
}

const DB_NAME = 'chengdu_school_db';
const DB_VERSION = 1;
const CLOUD_CONFIG_KEY = 'cloud_config';

// --- Mock Data ---
const MOCK_ADMIN: Recruiter = { id: 'admin-1', username: 'admin', role: 'admin' };
const ADMIN_PWD_KEY = 'admin_password';
const DEFAULT_PASSWORD = 'system123@';

// --- DB Initialization ---
let dbPromise: Promise<IDBPDatabase<SchoolDB>>;

const getDB = () => {
  if (!dbPromise) {
    dbPromise = openDB<SchoolDB>(DB_NAME, DB_VERSION, {
      upgrade(db) {
        if (!db.objectStoreNames.contains('students')) {
          const studentStore = db.createObjectStore('students', { keyPath: 'id' });
          studentStore.createIndex('by-date', 'reportTime');
        }
        if (!db.objectStoreNames.contains('appUsers')) {
          const userStore = db.createObjectStore('appUsers', { keyPath: 'id' });
          userStore.createIndex('by-idCard', 'idCard', { unique: true });
        }
        if (!db.objectStoreNames.contains('settings')) {
          db.createObjectStore('settings');
        }
      },
    }).catch(err => {
        console.error("Failed to open database", err);
        throw err;
    }) as any;
  }
  return dbPromise;
};

const generateId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

// --- Cloud Configuration Helpers ---

export const getCloudConfig = async (): Promise<CloudConfig | null> => {
  const db = await getDB();
  return (await db.get('settings', CLOUD_CONFIG_KEY)) || null;
};

export const saveCloudConfig = async (config: CloudConfig): Promise<void> => {
  const db = await getDB();
  await db.put('settings', config, CLOUD_CONFIG_KEY);
  window.dispatchEvent(new Event('settings-updated'));
};

/**
 * Generic Request Handler
 * - Firebase: Uses path-based REST API
 */
const cloudRequest = async (path: string, method: string = 'GET', body?: any) => {
  const config = await getCloudConfig();
  if (!config || !config.enabled || !config.dbUrl) return null;
  if (config.type !== 'firebase') return null;

  try {
    let url = `${config.dbUrl}/${path}.json`;
    if (config.dbSecret) {
      url += `?auth=${config.dbSecret}`;
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 5000); // 5s timeout

    const response = await fetch(url, {
      method,
      body: body ? JSON.stringify(body) : undefined,
      headers: { 'Content-Type': 'application/json' },
      signal: controller.signal
    });

    clearTimeout(timeoutId);
    if (!response.ok) throw new Error(`Cloud request failed`);
    return response.json();
  } catch (e) {
    return null; 
  }
};

// --- HTTP FILE SYNC HELPERS ---

const isValidUrl = (urlString: string) => {
  try {
    new URL(urlString);
    return true;
  } catch (e) {
    return false;
  }
};

const joinUrl = (base: string, file: string) => {
    const cleanBase = base.replace(/\/+$/, '');
    return `${cleanBase}/${file}`;
};

/**
 * Syncs specific data buckets from the server (JSON files)
 * target: 'all', 'data' (students), 'settings' (config/users)
 */
const syncFromServer = async (config: CloudConfig, target: 'all' | 'data' | 'settings' = 'all'): Promise<void> => {
  if (!config.dbUrl || !isValidUrl(config.dbUrl)) return;

  const headers: HeadersInit = {};
  if (config.dbSecret) {
      headers['Authorization'] = `Bearer ${config.dbSecret}`;
      headers['X-Api-Key'] = config.dbSecret;
  }

  // Helper to fetch a JSON file
  const fetchJson = async (filename: string) => {
      try {
        const urlObj = new URL(joinUrl(config.dbUrl, filename));
        urlObj.searchParams.append('_t', Date.now().toString()); // Cache buster

        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 5000);

        const res = await fetch(urlObj.toString(), { method: 'GET', headers, signal: controller.signal });
        clearTimeout(timeoutId);

        if (res.ok) return await res.json();
      } catch (e) { /* ignore network error */ }
      return null;
  };

  const db = await getDB();
  const tx = db.transaction(['students', 'appUsers', 'settings'], 'readwrite');

  // 1. Fetch & Restore Settings (settings.json)
  if (target === 'all' || target === 'settings') {
    const settingsData = await fetchJson('settings.json');
    if (settingsData) {
        if (Array.isArray(settingsData.appUsers)) {
            await tx.objectStore('appUsers').clear();
            for (const u of settingsData.appUsers) await tx.objectStore('appUsers').put(u);
        }
        if (settingsData.systemConfig) {
            await tx.objectStore('settings').put(settingsData.systemConfig, 'system_config');
        }
        if (settingsData.adminPassword) {
            await tx.objectStore('settings').put(settingsData.adminPassword, ADMIN_PWD_KEY);
        }
    }
  }

  // 2. Fetch & Restore Students (students.json)
  if (target === 'all' || target === 'data') {
    const studentsData = await fetchJson('students.json');
    if (studentsData && Array.isArray(studentsData.students)) {
        await tx.objectStore('students').clear();
        for (const s of studentsData.students) await tx.objectStore('students').put(s);
    }
  }

  await tx.done;
  if (target === 'all' || target === 'data') window.dispatchEvent(new Event('students-updated'));
  if (target === 'all' || target === 'settings') window.dispatchEvent(new Event('settings-updated'));
};

/**
 * Uploads specific data bucket to the server
 * target: 'data' (students.json) or 'settings' (settings.json)
 */
const syncToServer = async (config: CloudConfig, target: 'data' | 'settings'): Promise<void> => {
  const baseUrl = config.writeUrl || config.dbUrl;
  if (!baseUrl || !isValidUrl(baseUrl)) return;

  try {
    const payloadJson = await generateFilePayload(target);
    const filename = target === 'data' ? 'students.json' : 'settings.json';

    const headers: HeadersInit = { 'Content-Type': 'application/json' };
    if (config.dbSecret) {
      headers['Authorization'] = `Bearer ${config.dbSecret}`;
      headers['X-Api-Key'] = config.dbSecret;
    }

    // Append filename param for generic upload scripts
    const urlObj = new URL(baseUrl);
    urlObj.searchParams.append('file', filename);

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 8000);

    const response = await fetch(urlObj.toString(), {
      method: 'POST',
      body: payloadJson,
      headers,
      signal: controller.signal
    });

    clearTimeout(timeoutId);
  } catch (e) {
    // Suppress upload errors
  }
};

/**
 * Helper to generate the exact JSON content for the files
 * Used for both Sync and manual download initialization
 */
export const generateFilePayload = async (type: 'data' | 'settings'): Promise<string> => {
  const db = await getDB();
  if (type === 'data') {
    const students = await db.getAll('students');
    return JSON.stringify({ students, timestamp: new Date().toISOString() }, null, 2);
  } else {
    const appUsers = await db.getAll('appUsers');
    const systemConfig = await db.get('settings', 'system_config');
    const adminPassword = await db.get('settings', ADMIN_PWD_KEY);
    return JSON.stringify({ 
      appUsers: appUsers || [], 
      systemConfig: systemConfig || null, 
      adminPassword: adminPassword || null,
      timestamp: new Date().toISOString() 
    }, null, 2);
  }
};

// --- Student Operations ---

export const getStudents = async (): Promise<Student[]> => {
  const config = await getCloudConfig();

  if (config?.enabled) {
      if (config.type === 'firebase') {
          try {
            const data = await cloudRequest('students');
            if (data) return Object.values(data) as Student[];
          } catch(e) {}
      } else if (config.type === 'http_file') {
          // Force sync data file to ensure consistency
          await syncFromServer(config, 'data');
      }
  }

  const db = await getDB();
  const students = await db.getAll('students');
  return students.sort((a, b) => new Date(b.reportTime).getTime() - new Date(a.reportTime).getTime());
};

export const saveStudent = async (student: Omit<Student, 'id' | 'reportTime'>): Promise<Student> => {
  const newStudent: Student = {
    ...student,
    id: generateId(),
    reportTime: new Date().toISOString(),
  };

  const db = await getDB();
  await db.put('students', newStudent);

  const config = await getCloudConfig();
  if (config?.enabled) {
    if (config.type === 'firebase') {
      cloudRequest(`students/${newStudent.id}`, 'PUT', newStudent).catch(() => {});
    } else if (config.type === 'http_file') {
      syncToServer(config, 'data').catch(() => {});
    }
  }

  window.dispatchEvent(new Event('students-updated'));
  return newStudent;
};

export const deleteStudent = async (id: string): Promise<void> => {
  const db = await getDB();
  await db.delete('students', id);

  const config = await getCloudConfig();
  if (config?.enabled) {
    if (config.type === 'firebase') {
      cloudRequest(`students/${id}`, 'DELETE').catch(() => {});
    } else if (config.type === 'http_file') {
      syncToServer(config, 'data').catch(() => {});
    }
  }

  window.dispatchEvent(new Event('students-updated'));
};

