export const getAppUsers = async (): Promise<AppUser[]> => {
  const config = await getCloudConfig();
  if (config?.enabled) {
    if (config.type === 'firebase') {
       const data = await cloudRequest('appUsers');
       return data ? (Object.values(data) as AppUser[]) : [];
    } else if (config.type === 'http_file') {
       try {
         await syncFromServer(config, 'settings');
       } catch (e) {
         console.warn("Settings sync failed, falling back to local DB", e);
       }
    }
  }

  const db = await getDB();
  return db.getAll('appUsers');
};

export const saveAppUser = async (user: Omit<AppUser, 'id' | 'createdAt' | 'role'>): Promise<AppUser> => {
