    const file = event.target.files?.[0];
    if (!file) return;

    if (file.size > 1024 * 1024) {
      alert("为了保证系统性能，图片大小不能超过 1MB。");
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      setSettings(prev => ({ ...prev, logoUrl: base64String }));
    };
    reader.readAsDataURL(file);
  };

  const triggerFileUpload = () => {
    fileInputRef.current?.click();
  };

  // --- Backup & Restore Handlers ---

  const handleExportBackup = async () => {
    try {
      const jsonString = await getFullBackup();
      const blob = new Blob([jsonString], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      const dateStr = new Date().toISOString().split('T')[0];
      link.download = `school_db_backup_${dateStr}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } catch (e) {
      alert("导出备份失败");
      console.error(e);
    }
  };

  const handleImportBackup = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!confirm("高风险操作：恢复备份将完全覆盖当前的【所有数据】。\n\n建议在恢复前先导出当前数据作为备份。\n\n确定要继续吗？")) {
      if (backupInputRef.current) backupInputRef.current.value = '';
      return;
    }

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const content = e.target?.result as string;
        const result = await restoreFromBackup(content);
        if (result.success) {
          alert("数据恢复成功！系统将刷新以应用更改。");
          window.location.reload();
        } else {
          alert(`恢复失败: ${result.message}`);
        }
      } catch (err) {
        alert("恢复过程中发生错误");
        console.error(err);
      }
    };
    reader.readAsText(file);
    if (backupInputRef.current) backupInputRef.current.value = '';
  };

