      {showPwdModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm p-6 relative">
            <button onClick={() => setShowPwdModal(false)} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"><X size={20} /></button>
            <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center gap-2"><Lock size={18} className="text-[#05A7E2]" /> 修改管理员密码</h3>
            <form onSubmit={handlePasswordChange} className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">当前密码</label>
                <input type="password" value={oldPwd} onChange={(e) => setOldPwd(e.target.value)} className="w-full px-3 py-2 bg-gray-100 border-0 rounded-lg text-gray-900" />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">新密码</label>
                <input type="password" value={newPwd} onChange={(e) => setNewPwd(e.target.value)} className="w-full px-3 py-2 bg-gray-100 border-0 rounded-lg text-gray-900" />
              </div>
              {pwdError && <p className="text-red-500 text-xs">{pwdError}</p>}
              {pwdSuccess && <p className="text-green-500 text-xs">{pwdSuccess}</p>}
              <button type="submit" className="w-full bg-[#05A7E2] text-white py-2.5 rounded-lg font-medium hover:bg-sky-600 transition">确认修改</button>
            </form>
          </div>
        </div>
      )}

      {/* Add User Modal */}
      {showUserModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm p-6 relative">
            <button onClick={() => setShowUserModal(false)} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600"><X size={20} /></button>
            <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center gap-2"><Plus size={18} className="text-[#05A7E2]" /> 添加子管理员</h3>
            <form onSubmit={handleAddUser} className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">姓名</label>
                <input 
                  type="text" 
                  value={userFormName} 
                  onChange={(e) => setUserFormName(e.target.value)} 
                  className="w-full px-3 py-2 bg-gray-100 border-0 rounded-lg text-gray-900" 
                  placeholder="如: 李四"
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">身份证号 (用于登录密码)</label>
                <input 
                  type="text" 
                  value={userFormIdCard} 
                  onChange={(e) => setUserFormIdCard(e.target.value)} 
                  className="w-full px-3 py-2 bg-gray-100 border-0 rounded-lg text-gray-900 font-mono"
                  placeholder="18位身份证号"
                />
              </div>
              {userFormError && <p className="text-red-500 text-xs">{userFormError}</p>}
              <button type="submit" className="w-full bg-[#05A7E2] text-white py-2.5 rounded-lg font-medium hover:bg-sky-600 transition">确认添加</button>
            </form>
          </div>
        </div>
      )}

    </div>
  );
};

export default AdminDashboard;

import React, { useState } from 'react';
import { User, CheckCircle, Smartphone, LogOut, PlusCircle, Send, AlertTriangle, Home } from 'lucide-react';
import { saveStudent, isReportingTimeValid } from '../services/dataService';
import { Recruiter } from '../types';

interface Props {
  user: Recruiter;
  onLogout: () => void;
  onBack?: () => void;
}

const StudentForm: React.FC<Props> = ({ user, onLogout, onBack }) => {
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [contactType, setContactType] = useState<'student' | 'parent'>('student');
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      // 1. Time Window Validation (Async)
      const timeCheck = await isReportingTimeValid();
      if (!timeCheck.valid) {
        setError(timeCheck.message || '当前不在报备时间内');
        setLoading(false);
        return;
      }

      // 2. Input Validation
      if (!name || !phone) {
        setError('请填写所有必填项');
        setLoading(false);
        return;
      }

      // 3. Save
      await saveStudent({
        name,
        phoneNumber: phone,
        contactType,
        recruiterId: user.id, // For reporters, this is the phone number
        recruiterName: user.username, // This is the name entered on login screen
        recruiterPhone: user.id // Explicitly save the phone number for display columns
      });
      setSubmitted(true);
    } catch (err) {
      setError('提交失败，请重试');
    } finally {
      setLoading(false);
    }
  };

  const handleNext = () => {
    setSubmitted(false);
    setName('');
    setPhone('');
    setContactType('student');
    setError('');
  };

  if (submitted) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-school-50 p-6 animate-in fade-in duration-300">
        <div className="bg-white p-8 rounded-3xl shadow-xl w-full max-w-md text-center">
          <div className="bg-green-100 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6">
             <CheckCircle className="w-10 h-10 text-green-600" />
          </div>
          <h2 className="text-2xl font-bold text-gray-800 mb-2">报备成功!</h2>
          <div className="bg-gray-50 rounded-xl p-4 mb-6 text-left">
            <p className="text-sm text-gray-500 mb-1">已录入学生:</p>
            <p className="text-lg font-bold text-gray-900">{name}</p>
            <div className="mt-2 flex items-center gap-2">
              <span className="text-xs px-2 py-1 bg-blue-100 text-blue-700 rounded">
                {contactType === 'student' ? '学生电话' : '家长电话'}
              </span>
              <span className="text-sm text-gray-600">{phone}</span>
            </div>
          </div>
          <button
            onClick={handleNext}
            className="w-full bg-school-600 text-white py-3.5 rounded-xl font-bold shadow-lg shadow-blue-200 hover:bg-school-700 transition duration-200 flex items-center justify-center gap-2"
          >
            <PlusCircle size={20} /> 报备下一位
          </button>

          <button
            onClick={onLogout}
            className="w-full mt-4 text-gray-500 py-3 text-sm font-medium hover:text-gray-700 hover:bg-gray-50 rounded-xl transition flex items-center justify-center gap-2"
          >
            <LogOut size={16} /> 退出
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-safe">
      {/* Mobile App Header */}
      <div className="bg-school-600 text-white pt-safe sticky top-0 z-30 shadow-md">
        <div className="px-4 py-4 flex justify-between items-center">
          <div>
            <h1 className="text-2xl font-bold">成都城市建设技工学校</h1>
            <p className="text-xs text-blue-100 opacity-90">信息报备 • {user.username}</p>
          </div>
          <button 
            onClick={onLogout}
            className="text-xs bg-school-700/50 backdrop-blur-sm px-3 py-1.5 rounded-full hover:bg-school-700 transition flex items-center gap-1 border border-white/20"
          >
            <LogOut size={12} /> 退出
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-md mx-auto p-4">
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-1 h-full bg-school-500"></div>
          <h2 className="text-xl font-bold text-gray-900 mb-6">录入学生信息</h2>

          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Name Input */}
            <div className="space-y-2">
              <label className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                <User size={18} className="text-school-500" /> 学生姓名
              </label>
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="请输入姓名"
                className="w-full px-4 py-3.5 rounded-xl bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 focus:bg-white outline-none transition text-gray-900 placeholder-gray-400"
              />
            </div>

            {/* Phone Input with Type Selection */}
            <div className="space-y-2">
              <label className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                <Smartphone size={18} className="text-school-500" /> 联系电话
              </label>
              <div className="flex gap-2 mb-2">
                <button
                  type="button"
                  onClick={() => setContactType('student')}
                  className={`flex-1 py-2 text-xs font-medium rounded-lg border transition ${contactType === 'student' ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-gray-100 border-transparent text-gray-500'}`}
                >
                  学生本人
                </button>
                <button
                  type="button"
                  onClick={() => setContactType('parent')}
                  className={`flex-1 py-2 text-xs font-medium rounded-lg border transition ${contactType === 'parent' ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-gray-100 border-transparent text-gray-500'}`}
                >
                  家长
                </button>
              </div>
              <input
                type="tel"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                placeholder={contactType === 'student' ? "请输入学生电话" : "请输入家长电话"}
                className="w-full px-4 py-3.5 rounded-xl bg-gray-100 border-0 focus:ring-2 focus:ring-school-500 focus:bg-white outline-none transition text-gray-900 placeholder-gray-400"
              />
            </div>

            {error && (
              <div className="p-3 bg-red-50 text-red-600 text-sm rounded-xl border border-red-100 flex items-start gap-2">
                 <AlertTriangle size={16} className="mt-0.5 shrink-0" /> 
                 <span>{error}</span>
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-school-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg shadow-blue-200 hover:bg-school-700 transition duration-200 flex items-center justify-center gap-2 mt-4 disabled:opacity-50"
            >
              <Send size={20} /> {loading ? '提交中...' : '立即报备'}
            </button>
          </form>
        </div>

        <p className="text-center text-[#05A7E2] text-xs mt-6">
          成都城市建设技工学校 • 报备系统
        </p>
      </div>
    </div>
  );
};

export default StudentForm;

import React, { useState, useEffect } from 'react';
import StudentForm from './components/StudentForm';
import AdminDashboard from './components/AdminDashboard';
import { Recruiter, SystemSettings } from './types';
import { loginAdmin, validateReporter, getSystemSettings, isReportingTimeValid } from './services/dataService';
import { Smartphone, Monitor, Lock, Clock, User, ChevronRight } from 'lucide-react';

type SystemMode = 'PORTAL' | 'STUDENT_APP' | 'ADMIN_APP';

const DEFAULT_LOGO = "https://pic1.imgdb.cn/item/69383a2df9354404e341391f.jpg";

const App: React.FC = () => {
  const [mode, setMode] = useState<SystemMode>('PORTAL');
  const [currentUser, setCurrentUser] = useState<Recruiter | null>(null);
  const [settings, setSettings] = useState<SystemSettings>({ reportingStartTime: null, reportingEndTime: null, logoUrl: '' });
  const [isTimeValid, setIsTimeValid] = useState<{valid: boolean, message?: string}>({valid: true});

  // Authentication State for sub-apps
  const [username, setUsername] = useState('');
  const [loginPhone, setLoginPhone] = useState('');
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  // 1. Initialize
  useEffect(() => {
    const initApp = async () => {
      try {
        // Clear any legacy session data to ensure clean state
        try {
          localStorage.removeItem('school_app_session');
        } catch (e) {
          // Ignore localStorage errors
        }

        // Load Settings
        const s = await getSystemSettings();
        setSettings(s);

        const t = await isReportingTimeValid();
        setIsTimeValid(t);

        // Handle URL Routing
        const params = new URLSearchParams(window.location.search);
        const appParam = params.get('app');
        if (appParam === 'student') {
          setMode('STUDENT_APP');
        } else if (appParam === 'admin') {
          setMode('ADMIN_APP');
        } else {
          setMode('PORTAL');
        }
      } catch (e) {
        console.error("App initialization failed", e);
        // Fallback to defaults if critical failure
        setSettings({ reportingStartTime: null, reportingEndTime: null, logoUrl: '' });
      }
    };

    initApp();

    const handlePopState = () => {
      // Strict Security: Clear user session on any history navigation (Back/Forward)
      setCurrentUser(null);
      setUsername('');
      setLoginPhone('');
      setPassword('');

      const params = new URLSearchParams(window.location.search);
      const appParam = params.get('app');
      if (appParam === 'student') {
        setMode('STUDENT_APP');
      } else if (appParam === 'admin') {
        setMode('ADMIN_APP');
      } else {
        setMode('PORTAL');
      }
    };

    // Sync settings across tabs
    const handleStorageChange = async () => {
      try {
        const s = await getSystemSettings();
        setSettings(s);
      } catch (e) {
        console.error("Failed to sync settings", e);
      }
    };

    window.addEventListener('popstate', handlePopState);
    window.addEventListener('settings-updated', handleStorageChange);

    return () => {
      window.removeEventListener('popstate', handlePopState);
      window.removeEventListener('settings-updated', handleStorageChange);
    };
  }, []);

  const changeMode = (newMode: SystemMode) => {
    setMode(newMode);
    const url = new URL(window.location.href);

    if (newMode === 'STUDENT_APP') {
      url.searchParams.set('app', 'student');
    } else if (newMode === 'ADMIN_APP') {
      url.searchParams.set('app', 'admin');
    } else {
      url.searchParams.delete('app');
    }

    // Fix: Pass string to pushState to avoid potential object errors
    try {
      window.history.pushState({}, '', url.toString());
    } catch (e) {
      console.error("Push state failed", e);
    }
  };

  const handleLogin = async (e: React.FormEvent, targetRole: 'user' | 'admin') => {
    e.preventDefault();
    setLoginError('');
    setIsLoading(true);

    try {
        if (!username.trim()) {
          setLoginError('请输入账号/姓名');
          setIsLoading(false);
          return;
        }

        // --- Admin Login ---
        if (targetRole === 'admin') {
          if (!password) {
            setLoginError('请输入密码 (或子管理员身份证号)');
            setIsLoading(false);
            return;
          }

          const adminUser = await loginAdmin(username.trim(), password.trim());
          if (adminUser) {
            setCurrentUser(adminUser);
          } else {
            setLoginError('登录失败：账号或密码错误');
          }
          setIsLoading(false);
          return;
        } 

        // --- Student/User Login (Information Reporting) ---
        if (targetRole === 'user') {
          // Check if reporting time window is valid (Backup check)
          const timeCheck = await isReportingTimeValid();
          if (!timeCheck.valid) {
            setLoginError(timeCheck.message || '当前不在报备时间内');
            setIsLoading(false);
            return;
          }

          if (!loginPhone.trim()) {
            setLoginError('请输入手机号码');
            setIsLoading(false);
            return;
          }

          const user = validateReporter(username.trim(), loginPhone.trim());

          if (user) {
            setCurrentUser(user);
          } else {
            setLoginError('登录失败：请输入有效的11位手机号码');
          }
          setIsLoading(false);
        }
    } catch (err) {
        setLoginError('系统错误，请重试');
        setIsLoading(false);
    }
  };

  const handleLogout = () => {
    // Direct logout without confirm if confirm causes issues (Uncaught errors)
    let shouldLogout = true;
    try {
        shouldLogout = confirm("确定要退出登录吗？");
    } catch(e) {
        console.error("Confirm dialog failed", e);
        // If confirm fails, we assume user wants to logout to prevent being stuck
        shouldLogout = true;
    }

    if (shouldLogout) {
      setCurrentUser(null);
      setUsername('');
      setLoginPhone('');
      setPassword('');
      setLoginError('');
      // Crucial: Do NOT call changeMode('PORTAL'). 
      // Staying in current mode ensures we render the Login Screen for that mode.
    }
  };

  const handleBackToHome = () => {
    // Force logout when returning to home from student form
    setCurrentUser(null);
    setUsername('');
    setLoginPhone('');
    changeMode('PORTAL');
  };

  // --- PORTAL VIEW ---
  if (mode === 'PORTAL') {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-4xl">
          <div className="text-center mb-16">
            <img 
              src={settings.logoUrl || DEFAULT_LOGO} 
              alt="Chengdu School Logo" 
              className="w-32 h-32 mx-auto mb-8 object-contain drop-shadow-lg"
            />
            <h1 className="text-4xl md:text-6xl font-extrabold text-[#05A7E2] tracking-tight leading-tight">
              成都城市建设技工学校
            </h1>
            <p className="text-gray-500 mt-4 text-xl">综合信息管理平台</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <button 
              onClick={() => changeMode('STUDENT_APP')}
              className="group relative bg-white rounded-3xl p-8 shadow-xl hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1 text-left overflow-hidden border border-gray-100 ring-1 ring-gray-100"
            >
              <div className="absolute top-0 right-0 bg-blue-50 w-32 h-32 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110"></div>
              <div className="relative z-10">
                <div className="bg-blue-100 w-14 h-14 rounded-2xl flex items-center justify-center mb-6 text-blue-600 group-hover:bg-blue-600 group-hover:text-white transition-colors">
                  <Smartphone size={28} />
                </div>
                <h2 className="text-2xl font-bold text-gray-800 mb-2">信息报备</h2>
                <p className="text-gray-500 mb-6">H5 移动端 • 新生信息录入</p>
                <div className="flex items-center text-blue-600 font-semibold group-hover:translate-x-2 transition-transform">
                  进入系统 <ChevronRight className="ml-1" size={20} />
                </div>
              </div>
            </button>

            <button 
              onClick={() => changeMode('ADMIN_APP')}
              className="group relative bg-gray-50 rounded-3xl p-8 shadow-xl hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1 text-left overflow-hidden border border-gray-200"
            >
              <div className="absolute top-0 right-0 bg-gray-200 w-32 h-32 rounded-bl-full -mr-8 -mt-8 transition-transform group-hover:scale-110 opacity-50"></div>
              <div className="relative z-10">
                <div className="bg-white w-14 h-14 rounded-2xl flex items-center justify-center mb-6 text-gray-700 group-hover:bg-gray-800 group-hover:text-white transition-colors shadow-sm">
                  <Monitor size={28} />
                </div>
                <h2 className="text-2xl font-bold text-gray-900 mb-2">管理后台</h2>
                <p className="text-gray-500 mb-6">Web 端 • 数据管理与分析</p>
                <div className="flex items-center text-gray-700 font-semibold group-hover:translate-x-2 transition-transform">
                  进入后台 <ChevronRight className="ml-1" size={20} />
                </div>
              </div>
            </button>
          </div>

          <p className="text-center text-gray-400 text-sm mt-12">
             请选择对应的入口进入系统
          </p>
        </div>
      </div>
    );
  }

  // --- STUDENT APP FLOW (Information Reporting) ---
  if (mode === 'STUDENT_APP') {

    if (!currentUser && !isTimeValid.valid) {
        return (
            <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
                <div className="bg-white p-10 rounded-3xl shadow-xl w-full max-w-sm text-center border border-gray-100">
                    <div className="w-20 h-20 bg-red-50 rounded-full flex items-center justify-center mx-auto mb-6 text-red-500 ring-8 ring-red-50/50">
                        <Clock size={40} />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-900 mb-3">报备已过期或尚未开启报备</h2>
                    <p className="text-gray-500 text-sm leading-relaxed border-t border-b border-gray-100 py-4">
                        {isTimeValid.message}
                    </p>
                </div>
                <div className="mt-8 opacity-40 grayscale flex flex-col items-center gap-2">
                    <img src={settings.logoUrl || DEFAULT_LOGO} className="h-8 object-contain" />
                    <span className="text-xs text-gray-400">成都城市建设技工学校</span>
                </div>
            </div>
        );
    }

    if (!currentUser) {
      return (
        <div className="min-h-screen bg-white flex flex-col">
          <div className="flex-1 flex flex-col justify-center px-6">
            <div className="w-full max-w-sm mx-auto">
              <div className="text-center mb-10">
                 {/* Logo Area */}
                <div className="w-24 h-24 mx-auto mb-4 flex items-center justify-center">
                   <img 
                      src={settings.logoUrl || DEFAULT_LOGO} 
                      alt="Logo" 
                      className="w-full h-full object-contain"
                    />
                </div>

                <h2 className="text-3xl font-bold text-[#05A7E2] mb-2">成都城市建设技工学校</h2>
                <h1 className="text-xl font-bold text-gray-900">信息报备</h1>
                <p className="text-gray-500 text-sm mt-2">请输入姓名和手机号开始录入</p>
              </div>
              <form onSubmit={(e) => handleLogin(e, 'user')} className="space-y-6">

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">姓名</label>
                  <div className="relative">
                    <input
                      type="text"
                      value={username}
                      onChange={(e) => setUsername(e.target.value)}
                      className="w-full pl-10 pr-4 py-4 rounded-xl bg-gray-50 border border-gray-200 focus:ring-2 focus:ring-school-500 focus:bg-white transition text-gray-900 placeholder-gray-400"
                      autoComplete="off"
                      placeholder="请输入您的姓名"
                    />
                    <User className="absolute left-3 top-4 text-gray-400" size={20} />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">手机号码</label>
                  <div className="relative">
                    <input
                      type="tel"
                      value={loginPhone}
                      onChange={(e) => setLoginPhone(e.target.value)}
                      className="w-full pl-10 pr-4 py-4 rounded-xl bg-gray-50 border border-gray-200 focus:ring-2 focus:ring-school-500 focus:bg-white transition text-gray-900 placeholder-gray-400"
                      maxLength={11}
                      autoComplete="off"
                      placeholder="请输入11位手机号码"
                    />
                    <Smartphone className="absolute left-3 top-4 text-gray-400" size={20} />
                  </div>
                </div>

                {loginError && <p className="text-red-500 text-sm text-center bg-red-50 py-2 rounded-lg">{loginError}</p>}

